window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_015"]={"n":"成廷圭","dyn":"元","poems":[{"t":"夜过吴江宿于圣寿中复中行方丈","f":"五言律诗","c":["深夜扣禅扃，天寒月在庭。","鸟惊栖后树，僧掩读残经。","蔓草风吹白，枇杷雪洗青。","对床听法语，心孔愈惺惺。"]},{"t":"庞山湖泛舟过宁伯让庄所","f":"五言律诗","c":["湖上足清昼，雨馀生绿阴。","扁舟到城近，曲港入村深。","野叟频相问，郎君不可寻。","西庵肯分席，吾亦老山林。"]},{"t":"送智惠隐住水月禅院","f":"七言律诗","c":["放船直到栖禅处，万顷湖心一径开。","绿树鸟惊风落果，碧潭龙去水生苔。","西岩尊宿传灯在，东海高僧杖锡来。","今夜月明清似水，太空无地着纤埃。"]},{"t":"送谢芝甫赴山南宪","f":"七言律诗","c":["谢庭子弟多佳士，荆国山川总胜游。","万里捧书催入幕，一朝挝鼓发行舟。","玄猿啼处巴江夜，白雁来时楚甸秋。","襄汉风流千古意，为君长忆仲宣楼。"]},{"t":"夏日过万蓬庵","f":"七言律诗","c":["爱汝东庵暑气薄，解衣盘礴坐莓苔。","一林绿竹尽可数，五月白莲犹未开。","捉麈谈禅知独往，买鱼沽酒待重来。","沧江日落山更好，且放轻舟缓缓回。"]},{"t":"登望江亭","f":"五言律诗","c":["长江不可极，岸帻独登临。","潮信自朝暮，山光无古今。","碑亭流水涸，辇路积苔深。","欲写兴亡恨，西风万叶吟。"]},{"t":"长江送别图题送周平叔之通州丞","f":"七言古诗","c":["福山苍苍倚天碧，狼山巉巉生铁色。","两山当江作海门，力尽神鞭驱不得。","沧波万里从西来，楚尾吴头天一壁。","阴风转地鲸怒翻，黑雾连空龙起立。","来舟去楫不敢动，袖手傍观唯叹息。","扶桑浴日飞上天，百怪潜消杳无迹。","水光镜净山亦佳，目送云帆高百尺。","青霄要路君既官，白首穷途我犹客。","烟中隐隐见孤城，令我思乡心转剧。","《骊驹》歌罢将奈何，倚杖江南望江北。"]},{"t":"江南曲","f":"七言律诗","c":["吴姬当垆新酒香，翠绡短袂红罗裳。","二盆十千买一斗，三杯五杯来劝郎。","落花不解留春住，似欲随郎渡江去。","酒醒一夜怨鹃啼，明日兰舟泊何处。"]},{"t":"八月十六日送张仲举至秦邮驿是夕邵文卿置酒云峰台望月二首 其二","f":"七言律诗","c":["云峰台上今宵月，奇绝平生此一行。","天水光摇秋万顷，星河凉转夜三更。","谪仙被酒骑鲸去，游女吹箫学凤鸣。","明发星槎上河汉，定传诗话到蓬瀛。"]},{"t":"环碧斋","f":"七言律诗","c":["面面溪光护石苔，轩墀无复有尘埃。","月涵虚白浮秋去，水泛空青入座来。","渔钓儿孙多质朴，啸歌鸥鹭不惊猜。","我家亦住沧江曲，千个筼筜绕舍栽。"]},{"t":"操 题王彦龙藏三茅郎元隐墨兰","f":"楚辞体","c":["登勾曲兮常良，揽薜带兮筠裳。","絷白驹兮空谷，葆九凤兮扶桑。","汎光风兮既零雨，水浅浅兮石楚楚。","望夫君兮不来，怅清风兮日将暮。"]},{"t":"送周草窗尊师归庐山太平宫","f":"七言古诗","c":["匡庐之山仙所居，银河倒蘸青芙蕖。","三千里路昔一往，十八社友今何如。","向来匡君结庐处，至今海月悬高树。","水流花落春复春，洞府苍茫隔烟雾。","西风萧萧吹短衣，卖药修琴不归去。","浔阳潮落海欲枯，几时再得麻姑书。","桂风不跨林下虎，回仙肯顾盘中鱼。","幸留神物守丹鼎，近喜弟子迎飙车。","世间信有扬州鹤，看汝乘之上寥廓。","晴窗须理白云篇，爽气仍开紫霞阁。","袖中宝剑且藏锋，彭蠡小龙方睡着。"]},{"t":"题娄仲瑛山居图","f":"七言古诗","c":["近代几人画山水，郭畀无人朱敏死。","后之作者徒纷纶，得骨得皮谁得髓。","闻君扫却山居图，令我见之心独喜。","前山环伏似虎蹲，后山奔腾若龙起。","缘溪草堂星散居，嘉树阴阴云旎旎。","岂无采药古仙人，亦有看书两君子。","七十老翁居竹间，老去胡为在城市。","君如有意肯相过，貌得沧江弄清泚。"]},{"t":"送天长县学教谕孙允诚任满归金陵","f":"七言古诗","c":["忆昔君方少年日，文帝潜宫曾一识。","龙飞上天不可扳，图画空馀两奇石。","闭户读书三十秋，一线为官十领职。","天长令尹莫我知，苜蓿朝盘胜肉食。","三年官满来扬州，僦屋正近横江楼。","门前车马日如市，谈经讲易皆公侯。","公侯满座即沽酒，典却箧内青鼯裘。","乡心苦忆长干里，明日君当渡烟水。","中山李桓文中雄，乃是君之渭阳氏。","深衣再拜如母存，故宅重归令客喜。","岂无旧业问松筠，亦有清辉照桑梓。","青云熟路君何如，白发沧江吾老矣。"]},{"t":"丁十五歌","f":"曲","c":["丁十五，一百健儿如猛虎。","几年横行青海头，牛皮裁衫桑作弩。","射阳湖上水贼来，白昼杀人何可数。","将军宵遁旌旗空，倭甲蛮刀贼为主。","西村月黑妻哭夫，东坞山深母寻女。","屋庐烧尽将奈何，往往移家入城府。","不是丁家诸健儿，仗剑谁能剪狐鼠。","楼头酾酒齐唱歌，争剖贼心归衅鼓。","官中无文立赏功，还向山东贩盐去。"]},{"t":"春夜曲","f":"七言古诗","c":["芙蓉楼前拜新月，宝鸭微薰透银叶。","吴山楚水送远游，不管闺中照离别。","谁家玉钩飞上天，一似连环旧时缺。","缺多圆少将奈何，一寸愁肠万里结。","为郎白苧裁春衣，又恐月圆郎未归。"]},{"t":"戚戚行","f":"曲","c":["戚戚复戚戚，白头残兵向人泣。","短衣破绽露两肘，自说行年今七十。","军装费尽无一钱，旧岁官粮犹未得。","朝堂羽书昨日下，帅府然灯点军籍。","大男荷锸北开河，中男买刀南讨贼。","官中法令有程期，笳鼓发行星火急。","阿婆送子妇送夫，行者观之犹叹息。","老身今夕当守城，犹自支更月中立。"]},{"t":"射鸭谣","f":"七言古诗","c":["阿侬手挽竹枝弓，射鸭绿杨湖水东。","三三五五似学武，一箭误中双飞鸿。","前船唱歌后船哭，月黑湖中夜潜伏。","东海健儿不敢过，人命几如几上肉。","老翁入县前致词，夜夜全家犹野宿。","丁宁门户且勿开，明朝又怕官军来。"]},{"t":"哀老卒","f":"七言古诗","c":["白头老卒衣欲穿，日日织屦能几钱。","点名去讨海东贼，别家泣上城南船。","自云十五入行伍，掠阵争誇力如虎。","卖刀买酒看升平，六十年来不用武。","将军醉即骑马归，犹散黄金教歌舞。","中原上马贼更多，白昼杀人谁作主。","我今老去死即休，白骨填海何人收。","朝堂昨日下黄榜，谁家年少当封侯。"]},{"t":"闻中原河决盗起有感","f":"七言古诗","c":["中原九月黄河水，平陆鱼龙吹浪起。","飞霜萧萧鸿雁来，禾黍漂流桑枣死。","大风怒号扬飞尘，白昼剽掠如无人。","官军不诛海东贼，县吏乃杀西村民。","夜闻羽书起丁力，老稚嗷嗷向谁泣。","我当六十将奈何，扶杖淮南望淮北。"]},{"t":"题方方壶遥山古木图为桂元芳赋","f":"七言古诗","c":["千年老蛟方蜕骨，蹇偃长身擘厓出。","山樵熟视不敢近，似有雷霆护神物。","仙人来自方壶山，何以写此留人间。","樛枝风动铁交屈，苍皮雨溜苔斓斑。","芗溪先生读书处，对面高标起烟雾。","会将用汝作灵槎，八月因之上天去。"]},{"t":"熊松云画秋林诗意图送蔡伯雨道士归上清松云在淮阴今其来因见题以赠之就以柬送方壶隐者","f":"曲","c":["松云先生江海客，淮阴市中人不识。","惊风吹沙眼倦开，枕上青山归未得。","上清蔡君仙之徒，邂逅同觅黄公垆。","饮酣脱帽忽大叫，乘兴为写秋林图。","蔡君视之一抚掌，笔法拟我方方壶。","我家山中旧游处，如此长松几千树。","仙岩隐者抱琴来，鬼谷高人吃茶去。","先生有意肯相从，分与东头一间茆屋住。"]},{"t":"辛卯秋旱已极至八月晦天大雷雨","f":"七言古诗","c":["八月晦日雷怒号，大雨如注风萧骚。","捷如鬼神撼山岳，涌若江海翻波涛。","屋茅平卷一重去，河水忽涨三尺高。","惊鸿翅湿飞不起，散乱中泽呼其曹。","云龙有意洗兵甲，下与苍生舒郁陶。","浮云收敛赤日见，天宇廓远无纤毫。","岁年不逢亦偶尔，吾将种麦耕东皋。"]},{"t":"裴氏二节妇之诗为屯田房千户作","f":"七言古诗","c":["昔年夫君死漳戍，恨不从之泉下去。","有弟万里负骨归，获鹿原头与封树。","是时孤儿方学行，天地容身复何处。","此心匪石石可移，誓欲教儿如汝父。","儿成娶妇身始閒，一旦儿亡岂能顾。","妇姑相守到白头，至今不识门前路。","夫家赵郡知几年，乡里尝旌两节妇。","向来我识房将军，乃是节妇之侄孙。","岁时宁忘俎豆事，水旱肯废云山屯。","忠臣烈女有如此，千载义事辉高门。"]},{"t":"送万嘉会教谕之山阳","f":"七言古诗","c":["西江万君头戴笠，清时典教山阳邑。","王侯折简不可招，令尹之前只长揖。","深衣上堂开讲筵，衿佩铿锵如鹄立。","六经字字在所行，要使儒风更俗习。","朝盘苜蓿甘如饴，不羡诸公谋肉食。","人材作养期有成，他日当为教官式。"]},{"t":"湘江秋远图","f":"七言律诗","c":["苍梧愁云拂烟水，日暮无风波自起。","何人吹箫作凤凰，披发临江迎帝子。","黄陵女儿情更多，却掩冰弦泪如洗。","千年遗恨人不知，坐对空山疑梦里。"]},{"t":"送李教谕避乱归鄱阳","f":"七言古诗","c":["长淮九月秋风高，水怪百出生波涛。","吴樯楚柁不敢渡，人命委弃如鸿毛。","山精白昼作鬼语，野狐黑夜如人嗥。","县斋博士最忧者，中宵起听荒鸡号。","岂无强弩射其上，愁来磨损胸中刀。","平生读书弗见用，拂衣归卧番江皋。","知几未落季鹰后，对客且放元龙豪。","束书三日先告别，令我不乐心忉忉。","时运忽来乌可遏，忧患卒至将安逃。","高歌激烈不肯住，衰柳何以维轻舠。","临岐大醉意不已，更过西家沽酒醪。"]},{"t":"四明张文海母娄节妇诗","f":"曲","c":["贞节之妇何代无，大节直与忠臣俱。","高风凛凛出肝胆，皎如日月行天衢。","江淮丧乱复何有，衣冠扫地悲穷途。","眼明见此节妇传，胸中愤气为之苏。","夫君疾病有遗语，身后之事当何如。","上有高堂之老姑，下有乳哺之二雏。","浮云无根白日短，黄尘有尽沧溟枯。","沧溟易枯日易短，妾心到死终难渝。","夫君一去三十载，二雏茕立今为儒。","迩来世俗薄如纸，抚琴南望空嗟吁。","为臣不能报明主，七尺有躯空丈夫，呜呼七尺有躯空丈夫。"]},{"t":"半山歌为馀干周隐君作隐君早岁江湖中有半山行藁三十年晚归冠山终老焉","f":"七言古诗","c":["番阳台上生春草，湖外之山为谁好。","沧波日日送征帆，多少行人此中老。","翁昔少年初远游，吴楚东南事幽讨。","江海诗名三十年，尽揽风烟入行稿。","归卧冠山一半云，知足由来合天道。","黄金似水供岁时，白发如霜照清昊。","却留一半与诸君，若个似翁归亦早。","傍人错比争墩翁，翁若闻之应绝倒。"]},{"t":"雪中歌为王子中赋","f":"曲","c":["王郎不知何许人，一舟横泛江之滨。","风清月霁未肯出，沧洲独与天为邻。","洞庭烟水两寂寞，十年不见君山春。","北风三日雪大作，挂席张帆以为乐。","手中铁笛吹紫凰，身上?衣如白鹤。","拍浮满载百壶酒，奚足篷窗供独酌。","剡中隐者毋相疑，乃与戴老同襟期。","更阑酒尽雪未止，趣棹欲返犹迟迟。","今夕何夕此乘兴，千载未必无人知。"]},{"t":"悲徐州","f":"七言古诗","c":["彭城八月风尘起，数郡义兵多战死。","良家子女复何辜，尽作黄河水中鬼。","髑髅填海几时归，千古沉冤无处洗。","王师一日天上来，虏船夜斫浮桥开。","守桥将军不敢敌，狂澜倒泻声如雷。","三山回望平如掌，野旷犹闻金鼓响。","军中少年当封侯，争入辕门请功赏。","江边老翁死即休，血泪沾襟空白头。"]},{"t":"题画史王梦麟卷","f":"七言古诗","c":["老翁穷居广陵市，四壁萧然祗图史。","题诗不博一文钱，空瓦磨穷空费纸。","不如乡里诸妙年，翰墨游戏王公前。","解衣盘礴作山水，一幅何惜千金捐。","何人最得沧洲趣，麟也于今称独步。","狂吟寄兴肯相过，画我东桥竹居趣。"]},{"t":"延祐三年东平申屠先生掾山南宪司行部夷陵毁曹操祠为孔子庙歌颂赋论者夥矣后四十年余亦赋一首","f":"七言古诗","c":["西陵归来忽千古，操也何尝称魏武。","黄牛峡口不曾来，亦有巴人建祠宇。","巴人日日迎送神，男能唱歌女能舞。","一方说是鬼奸雄，血食依凭出巫语。","精灵托汝据荆襄，魂魄何由归邺许。","今年偶值申屠君，削吾尊罍彻吾俎。","茫茫穹壤复何之，夜夜荒林怨风雨。","无颜可见山阳公，有恨犹思茂陵土。","当时贼汉岂独孤，同日举兵皆可数。","高文一落在人间，只得群公诮狂虏。","寄与扶倾济弱人，慎勿欺心背其主。"]},{"t":"题顾秀才所藏舟中看月图","f":"曲","c":["放船晚作南湖游，一葫芦酒当船头。","白云翩衣紫霞帔，松风吹发寒飕飕。","少焉月出影零乱，散作百顷玻璃秋。","有月复有酒，不饮令人愁。","谪仙在何许，空葬青山头。","我家草堂月更好，何如返棹归来休。","归来休，痴人不饮月亦羞。","素娥起舞我摘阮，对饮岂必论觥筹，千载与月同风流。"]},{"t":"送澧州治中王伯颜征蛮诗","f":"七言古诗","c":["大风吹沙扬飞云，五溪白昼缠妖氛。","鼎民澒洞走无路，何人靖难收奇勋。","捍城惟称纳太守，杀贼惟数王将军。","将军行年未五十，上马挥戈勇无敌。","岛夷振动江水翻，日昃不令走一贼。","将军亦是人中雄，一日过我淮之东。","腰间宝刀血不灭，提出歘忽生悲风。","楼船载得诗千首，不羡黄金高北斗。","刻向武陵山上头，诗与英名同不朽。"]},{"t":"从军曲","f":"七言古诗","c":["征马萧萧车辘辘，年少儿郎新结束。","庙前无酒发行装，山路崎岖行未熟。","生来不识征战尘，骄马转鞍车折轴。","徘徊相顾奈尔何，丞相令严风火速。","妻子归来哭倚门，今夜夫君月中宿。"]},{"t":"谢雪坡送饶介之鲈鱼介之有歌索次其韵","f":"七言古诗","c":["松江之鲈长似人，网罟未敢伤其鳞。","今年八月欲上市，谢侯先得江之津。","筠篮急脚走相送，侑以菊露之清醇。","鲁阴先生不得吃，隔屋大叫呼西邻。","庖丁迎笑老饕喜，汲井洗出色胜银。","筛香捣辣给爨妇，去头截尾娱众宾。","吾侪醉饱谢侯德，此乐何啻千万缗。","吴王鲙残眇何许，阖闾城外犹风尘。","太羹玄酒久寂莫，世间滋味元非真。","先生欲眠客且去，勿论张翰争羹莼。"]},{"t":"奉书岳忠武王诗集传后","f":"七言古诗","c":["班师归来泪如雨，洒向北邙陵上土。","金杯不共半杯来，旌旆已入黄龙府。","奸秦柄国奈若何，世上英雄本无主。","谁人肯道莫须无，嗟尔张公作何语。","一朝行殿受封功，锡宴湖山看歌舞。","两宫万里尚龙沙，泉下臣飞心独苦。","臣家有子罪万死，臣心有血一斗许。","君王还肯北征时，留衅中军帐前鼓。","大河落日又风尘，抚卷令人哭忠武。"]},{"t":"马国瑞所题李龙眠画赤黑二马相戏卷子一轴索余题诗因题卷后","f":"曲","c":["君不见项王乌骓如黑龙，蹴踏万里烟尘空。","五年乘之勇无敌，七十二战收奇功。","又不见白门赤兔来向东，神物终属云长公。","百万军中刺名将，疾如健鹘追秋风。","龙眠居士亲貌得，毛色意态将无同。","沙场无人白日静，平陂浅草青茸茸。","双蹄直立欲变化，两尾突起争豪雄。","还君此图三叹息，此马忽去难再得。","江南异事人未知，又见麒麟出东壁。"]},{"t":"题笠泽金伯祥横山墓所之瞻云轩","f":"楚辞体","c":["踞湖之上几千尺，下有沧波通笠泽。","百年华屋与荒邱，两地相望泪沾臆。","亲殁知几年，抱痛如一日。","孤云飞处最关情，漠漠愁魂招不得。","魂之来兮云下垂，月落分明见颜色。","魂之去兮云亦空，歘忽消沈竟无迹。","悠悠飞去复飞来，孝子之心岂终极。","我家扬州好墓田，老作江南未归客。","天涯芳草又春深，梦里还家作寒食。"]},{"t":"题张天民荆南精舍","f":"楚辞体","c":["溪有蛟兮山有虎，欲往从之道应阻。","崩云堕地猿玃愁，腥风吹衣髑髅语。","花开静树自为春，木落深林响如雨。","斩蛟烈士呼不闻，骑驴老人去何许。","溪山良是村郭非，抚卷茫然心独苦。","日月徒为昼夜宾，江山本是兴亡主。","先生岁晚早归来，还使居民有环堵。"]},{"t":"谢冯仁伯惠双鸡","f":"七言律诗","c":["可人送我双鶤鸡，五色毛羽生方齐。","下堂呼儿解其缚，意欲飞上茅檐栖。","山家得鸡如得凤，宁与野雉论高低。","吾将洗鼎试灵药，白昼听尔云间啼。"]},{"t":"六合郭节之听琴诗卷","f":"七言古诗","c":["天下几人弹古琴，爱之不惜千黄金。","春雷上天霹雳死，至今古调空消沉。","金徽玉轸久寂莫，断文剥落尘埃侵。","钟期一去不复返，况乃四海无知音。","松风泠泠白日静，山水定以娱冲襟。","无弦之趣世莫识，悠悠千载渊明心。","古人今人若流水，善听善弹能有几。","六峰隐者吾故人，得天下名亦琴耳。"]},{"t":"槎山歌为胡云夫作广西宪史云夫家于德安之槎山累世矣至正十二年秋中台计事回至广陵闻汉上兵后山居亦荡然已慨然思亲而不可归冯太守书槎山二字为赠朝夕展玩姑慰其心因题卷后","f":"七言古诗","c":["淮水出自桐柏山，东流入海何时还。","胡君引水种林木，筑室正在槎山间。","槎山清空白日静，胡君意与云俱閒。","汉东一夕风尘起，云亦高飞几千里。","山间有家不得归，却过扬州饮淮水。","饮之为洗冰雪肠，今我不乐思故乡。","驱车明发渡远道，广海又在天一方。","思亲恨不归来早，梦中祗说槎山好。","他年归隐奉亲欢，白头同向槎山老。"]},{"t":"刘商观弈图","f":"七言古诗","c":["茅生绝艺天下无，何以刻此观弈图。","刘商见之亦惊倒，神妙似与龙眠俱。","松阴对弈者谁子，岂非角里园公乎。","云绡雾縠古冠佩，童颜雪顶沧溟枯。","野樵旁立太痴绝，归来始觉仙凡殊。","斧柯竟化作尘土，世间甲子真须臾。","老夫只解饮醇酒，一着输赢曾放手。","市廛有地寄閒身，却觅南山橘中叟。"]},{"t":"题墨梅卷子","f":"七言律诗","c":["千年老枝生铁色，雪魄冰魂谁貌得。","三生石上见逋仙，独鹤归来楚云黑。","何郎垂老客扬州，花前劝酒仍风流。","江城吹笛月未落，梦回一夜生春愁。"]},{"t":"题苏昌龄画秋江送别图赠湘中江可翁","f":"七言古诗","c":["白沙江头水杨树，正是秋风送君处。","海门日出潮欲平，把酒娱君君不住。","杨公庙前闻鼓声，多少行人此中去。","江子于今空复情，干戈满地兵纵横。","丹枫叶堕山鬼啸，黄竹丛薄饥鼯鸣。","湘中有家不得往，时对此图双眼明。"]},{"t":"李长卿遂乐轩","f":"七言古诗","c":["遂乐之轩何所遂，我识轩中主人意。","十年江海早归来，愿受城南一廛地。","男婚女嫁及此时，婢织奴耕供卒岁。","闭门不出心自怡，阿孙撰杖行相随。","绿阴无尘白日静，饥饱扪腹看花娱。","游鱼在藻弄清泚，好鸟当户鸣高枝。","几人适意有如此，乐乎天命复奚疑。"]},{"t":"宋君瑞存恕堂","f":"七言古诗","c":["故家独见宋先世，文采风流一儒素。","向来松雪写如心，题在南堂乐居处。","门前求药日纷纷，或有无钱亦持去。","子孙传之将百年，积券如山不知数。","君为郡马几叶孙，复戒诸郎祗存恕。","九街正尔黄尘深，杯酒对面干戈侵。","营营苟苟者谁子，一毫奚啻争千金。","傍人笑问尔何以，平生苦自如吾心。","还君此卷三叹息，坐隅自写为规箴。"]},{"t":"沽酒行","f":"七言古诗","c":["街头酒贵不可沽，渴吻甚欲吞江湖。","手持青钱宛若画，家僮走遍东西衢。","南桥沽来不满斗，就坊买得乌鸡雏。","烹鸡开酒忍独酌，可人好客难招呼。","今宵醉饱坐复醒，灯前不用儿孙扶。"]},{"t":"兵部危太朴郎中家于临川云林山上请方方壶作云林图太朴索诗赋此","f":"七言古诗","c":["宇宙有此云林山，三十六峰如髻鬟。","云林先生读书处，长松芝草非人间。","白云裁衣亦自足，青精制饭何曾悭。","朝光空濛起舒眺，人迹迥绝穷跻攀。","青天荡荡海月出，照见先生冰雪颜。","惟有方壶契幽眇，貌得彷佛来尘寰。","宫中圣人正问道，布衣召入蓬莱班。","玉堂给札纵挥洒，金匮启钥烦修删。","于今听履上霄汉，圣人未放先生还。","山中丧乱复何有，飞瀑落涧空潺湲。","青林鸟啼野花发，白昼虎啸松风閒。","朝廷宴坐见图画，亦应怀我双佩环。","方壶先生在何处，胡不同来玉京住。","鱼龙夜落河汉秋，却泛灵槎共归去。"]},{"t":"二月二十日同李希颜游范文正公义庄登天平灵岩两山希颜有诗因次其韵","f":"七言古诗","c":["阖闾城外草芊芊，桃花杏花红烂然。","物华两岸眼零乱，画船春水如登天。","棹歌却转横塘去，山寺钟声日将暮。","长松夹径风泠泠，曾是先贤旧行路。","老禅蔬食作清供，留宿白云最深处。","瓣香复拜忠烈祠，卮酒谁浇洛阳墓。","清谈朝士亦东来，白发野翁犹北至。","晓乘竹轿度羊肠，地豁川平还散步。","蕲王坟上无纸钱，却读残碑不成句。","一群山鸟自惊飞，无数野花空媚妩。","此中俯仰二十年，一废一兴皆可举。","濡毫拂石重题名，搔首临风谩怀古。","人生身后可奈何，欲乞南峰一抔土。","山灵有意肯相容，书券便当酬地主。"]},{"t":"夜泊陈店舟中写怀兼柬云林高士时张孟肤同舟","f":"七言古诗","c":["葑门晓发吴淞船，手把传符津吏前。","五年别家走未已，素发萧萧垂两肩。","小龙江头旧游处，东家西家争招延。","匆匆会散等过鸟，风吹湖水春无边。","云林高士独不见，倚篷四望心茫然。","惊湍叠浪岂作恶，渚花江草仍争妍。","夕阳收港泊陈店，入市买鱼烧荻鞭。","蓉城公子今最贤，赋诗行酒能周旋。","一谈一笑烛欲尽，野戍不闻钟鼓传。","却忆山中小儿女，如此明月应未眠。"]},{"t":"醉樵歌","f":"曲","c":["朝亦不采薪，暮亦不采薪。","莲泾赊得沽酒家，入口滑辣香且醇。","一饮三百钱，再饮五十文。","兴来连欲醉不得，一醉已判三千春。","狂歌还容木客和，大叫岂怕邻翁嗔。","生来无田种秫米，乱后有地披荆榛。","山花野草插满笠，儿曹错□刍荛民。","王质不饮酒，也是痴仙人。","烂柯山，在何许，一局残棋自今古。","当垆主人休索钱，酒债寻常何足数。","醒来随处束薪归，却卖青钱送还汝。"]},{"t":"和杨孟载春愁诗原韵录寄杨铁崖","f":"七言律诗","c":["小窗病酒厌厌卧，春色三分二分过。","仙人谩织藕丝长，金铜难补菱花破。","花间蛱蝶已双飞，叶底青梅才一个。","綵笔题诗人未归，愁肠一似车轮大。"]},{"t":"张士先双桂堂","f":"七言律诗","c":["淮南丛桂天下无，张侯堂前生两株。","清阴尝栖白顾兔，樛枝并立青珊瑚。","侯也生儿有如此，丹凤之雏骥之子。","素衣老仙天上来，捣熟玄霜先赠尔。"]},{"t":"题贺耕叟晚香亭","f":"五言古诗","c":["陶翁本爱菊，屈子亦餐英。","两贤天壤间，千古清风清。","翁乎饮辄醉，子也空独醒。","何如贺狂客，不羡身后名。","中州有沃壤，丧乱不得耕。","种菊数十本，得酒还自倾。","自歌仍自和，乌乌作商声。","陶然有馀乐，聊复全此生。"]},{"t":"赋得龙门恭送张德常同知之嘉定任","f":"五言古诗","c":["来龙起西北，万古壮此门。","日月互开阖，风云恒吐吞。","龙来海欲立，龙去天为昏。","至今两绝壁，上有波涛痕。","张公东海客，邀我坐石根。","仰瞻泰宇净，俯瞰灵湫浑。","神物固莫测，目击道乃存。","岁旱当用汝，霖雨清乾坤。"]},{"t":"仪真向有馆驿久废船马俱无使客不便省委宣使梁克诚振治一新粲然可观诸公有诗题赠因题卷后","f":"五言古诗","c":["昔游銮江城，曾过銮江驿。","庭庑阒无人，萧然草盈尺。","饥鸟噪前楹，羸马卧空枥。","乃知江南民，于焉久当役。","传吏苦诛求，日夜星火急。","使者既旁午，箠楚复交集。","省城若有忧，选官为苏息。","梁君英妙年，力可事繁剧。","朝迎南台官，暮送北省客。","高马驰若星，大舸密如织。","宿弊一洗清，长才世难得。","和气回闾阎，光华照原隰。","老夫作此歌，奚足颂其德。","岂无观风者，传之上京国。","驾言当趋装，秋霄起云翮。"]},{"t":"杂兴三首 其一","f":"五言古诗","c":["野蔓被长坂，秋花翳前林。","登高望孤冢，凉露忽已深。","团团日东出，瞬息还西沈。","吾亲不可见，哀涕沾衣襟。","徘徊未忍去，玄云生夕阴。"]},{"t":"杂兴三首 其二","f":"五言古诗","c":["遥遥烟中城，旗帜互明灭。","大风扬飞云，悲笳隐空堞。","独行临大河，足力稍衰歇。","褰衣欲涉之，水深不可涉。","吾生将焉归，谁与作舟楫。"]},{"t":"杂兴三首 其三","f":"五言古诗","c":["夜坐竹林下，仰视天茫茫。","浮云起西北，众星黯无光。","群鸟昧灵性，胡为思南翔。","良辰忽变易，志士徒悲伤。","愿尔保素节，何劳怨清商。"]},{"t":"赋樗杜之诗一首送大岁大彻二位上人归日本国樗杜之上人自号也","f":"五言古诗","c":["东海有樗木，托根扶桑边。","扶桑不汝弃，屈曲枝相连。","上拂火龙驭，下阴神鳌渊。","念彼拥肿物，岂无人所怜。","岁公见之喜，日夕相周旋。","手执天地炉，巢居在其颠。","朝持秘密咒，夜坐清净禅。","我欲从子去，一笑三千年。"]},{"t":"上丞相多尔济国王","f":"五言古诗","c":["太祖开中国，元臣起朔方。","八荒归版籍，千载际明良。","奕世兼茅土，闻孙列庙堂。","白麻新命相，紫诰旧封王。","镂玉为符契，镕金作印章。","既徵扶社稷，仍赉理阴阳。","辽海风尘静，梁园草木芳。","精忠存北阙，化泽被南荒。","翠织龙衣密，黄封蜜酒香。","三吴歌盛美，百辟仰辉光。","士已歌麟趾，人争睹凤凰。","小儒狂斐在，有颂继甘棠。"]},{"t":"瑞麟图至正己丑夏五月麟出泰兴县张村村民箠死之县尹冯君写为图请以赋之","f":"五言古诗","c":["麟也嗟如此，天乎涕独零。","江间消间气，天上失机星。","异瑞遵三代，嘉祥冠四灵。","拳挛宛马足，彷佛野麇形。","高冢云犹白，空林草自青。","无由歌一角，宜尔寿千龄。","同本时方验，归和世未听。","东川唐故事，西狩鲁遗经。","谩托犁牛子，虚期紫凤翎。","美兹贤令尹，见此古仪形。","画拟功臣阁，书归太史铭。","观风有使者，还与上明廷。"]},{"t":"题刘孝子传后泰州海陵县刘子彬性孝友与诸弟隐居读书耕以为养曲尽其道亲丧茔葬有异色蛇见又产连理木人以为孝感状元陈祖仁记其事司业江存礼因作刘孝子传为题其后","f":"五言古诗","c":["好在刘真士，家居海上村。","义风今益振，德望老逾尊。","谯国读书裔，吴陵孝友门。","白头共子职，粉骨恋亲恩。","养志兼甘旨，承欢适凊温。","难兄复难弟，贤子更贤孙。","联綵香凝席，鸣埙酒满樽。","秋田分黍稷，晓栅散鸡豚。","忽抱终天恨，同招九地魂。","苫茨忘夜寝，饘粥废朝飧。","手泽疑如在，音容俨若存。","断云丹旐远，良夜漆灯昏。","畚锸随佣作，衣裳积泪痕。","异蛇成五色，嘉树托孤根。","活水流芳泽，新茔启庆源。","已终丧次礼，犹奉梦中言。","善行能相感，乡评未易论。","名应动冠冕，心不愧乾坤。","芝草秋犹盛，荆花晚更繁。","门闾待旌表，会见薄夫敦。"]},{"t":"奉题李秋谷平章存日寄其叔父李同知安书后兼叙其实","f":"五言古诗","c":["秋谷文章在，清风四十年。","先朝真宰相，平地旧神仙。","逸气云霄上，荣光雨露边。","印章封一品，楮币赐三千。","忧国惟心切，匡时见节全。","回咨还内藏，知足契皇天。","忆自攀龙去，曾如抱虎眠。","过家期上冢，谢病请归田。","季父何时会，安书远道传。","喜看亲族贵，仍愿弟兄贤。","妙画何森若，真情亦霭然。","封缄题日月，光彩照山川。","未数甘棠笏，宜书汗竹编。","子孙须宝秘，什袭永绵绵。"]},{"t":"王彦芳御史所居之堂曰绣荣诸公诗题卷末","f":"五言古诗","c":["上国疏恩重，中台拜命初。","两朝司内府，十载奉宸居。","甫历参谋选，俄膺御史除。","天机织文绮，月姊绣华裾。","獬豸冠偏称，麒麟锦不如。","羽标金鸑鷟，花隐玉芙蕖。","六辔青骢马，双轮白鹭车。","胸蟠五色线，腹藁万言书。","被服身何忝，弥缝志必摅。","芬芳流简册，光彩照门闾。","退户香烟袅，垂帘化日舒。","小山蹲怪石，活水灌清渠。","昆季年皆妙，公卿驾不虚。","谩誇貂作帽，宁羡豹为祛。","庭训言犹在，乡情礼未疏。","每蒙招宴集，讵肯弃樵渔。","鹑结惭无褐，蜗藏仅有庐。","深期换朝服，紫带映金鱼。"]},{"t":"赋长律二十二韵题吴江郭州判索送谢太守诗卷","f":"五言古诗","c":["持节吴江日，分符槜李辰。","双螭交赤帜，五马挟朱轮。","冻雨连清道，灵风动洒尘。","字民亲若子，破敌捷如神。","水寺题诗遍，田家问俗频。","莺花苕霅晓，烟树洞庭春。","是处歌龚遂，连城借寇恂。","湖山当大郡，封壤接比邻。","在昔京都富，于今府库贫。","三苗空掠地，百粤阻通津。","赤县伤凋瘵，苍生受苦辛。","髓枯肤未剥，病亟气难伸。","画省持衡鉴，乌台列缙绅。","谈兵犹辩士，献策尚从人。","閒世才难得，如公孰与伦。","抚时先恺悌，起废莫因循。","城筑工尤大，田毛赋必均。","烬馀驱瓦砾，兵后剪荆榛。","惠化仍多举，祯祥或可臻。","铸钱资国费，赈粟散仓陈。","和气随天转，舆情与日新。","斐章书令德，史笔待词臣。"]},{"t":"故湖州路同知中宪郜公子敬挽章","f":"五言古诗","c":["昔日趋乌府，君年正黑头。","家承今阀阅，世出古诸侯。","夙有登车志，仍多为国谋。","浚湖陈上策，平寇借前筹。","泽国波澜息，蛮江雾雨收。","遥知鹰隼击，曾与凤凰游。","跋涉三千里，勤劳五十秋。","台评通北阙，士论溢南州。","广海绥南服，湘潭控上游。","三司劳赞画，两县起歌讴。","别驾恩初下，朝堂礼更优。","上书才告老，拂袖即归休。","乐矣陶潜酒，飘然范蠡舟。","春田苕水近，夏屋弁山幽。","洁以兰为佩，轻堪竹作兜。","儿官从此大，孙孝复何忧。","一日音容隔，群公涕泗流。","西轩情脉脉，东胜梦悠悠。","芝室人千古，花蹊土一抔。","明公发潜德，勒石表林邱。"]},{"t":"题郭行简照磨所有具庆堂诗十六韵","f":"五言古诗","c":["上国疏恩重，高堂衍庆新。","世当清化日，家有白头亲。","绮席团圞处，朱门富贵春。","儿孙纷满眼，夫妇敬如宾。","偕老期千载，生年并八旬。","阃仪仍肃肃，庭训尚谆谆。","食举齐眉案，花簪折角巾。","贤郎登仕版，硕德动朝绅。","盛事谐占凤，佳辰纪绂麟。","同称寿觞满，联舞綵衣频。","斸雪供青笋，开冰出锦鳞。","孝心应尽力，禄养必殊伦。","自古称三乐，于今复几人。","芬芳流简册，光彩照乡邻。","京兆看前辈，汾阳恐后身。","明年两封爵，颁诰下枫宸。"]},{"t":"送郭仲安贡察院","f":"五言律诗","c":["捧檄上京华，清才素共誇。","封章不起草，健笔自生花。","燕市千金马，天河八月槎。","看君冠獬豸，好为触奸邪。"]},{"t":"登多景楼怀唯心上人","f":"五言律诗","c":["凭高望不极，多景复多愁。","落日随天转，空江入海流。","渔樵何处老，兵甲几时休。","却忆唯心叟，题诗在上头。"]},{"t":"六月八日","f":"五言律诗","c":["世事今如此，吾生可奈何。","海东仍盗贼，颍上复干戈。","苦雨朝逾急，阴风夜转多。","白头无寸策，对酒独悲歌。"]},{"t":"送潘仲明医谕之泰兴","f":"五言律诗","c":["舟行三百里，直到县门前。","不请居官俸，多收卖药钱。","年丰沙米贱，江近网鱼鲜。","莫起归来兴，于今令尹贤。"]},{"t":"刘庄","f":"五言律诗","c":["刘庄久不到，草树郁苍苍。","野艇买瓜果，村坊罗酒浆。","水生沙井浅，潮上卤田荒。","时共西清老，登高望夕阳。"]},{"t":"晓出钱塘门","f":"五言律诗","c":["出门聊适意，草树碧纷纷。","一雨破清晓，四山生白云。","僧楼缘岭出，樵径过桥分。","明日重携酒，来浇和靖坟。"]},{"t":"斋居","f":"五言律诗","c":["晓起坐终日，无人扣竹扉。","柿因风落早，菊为雨开迟。","稚子能赊酒，邻翁许借诗。","白头无别计，空负圣明时。"]},{"t":"寄吴寅甫","f":"五言律诗","c":["山馆残花歇，江楼暮雨馀。","长歌留客和，短札倩人书。","露叶悬青蔓，风帘隐碧梧。","夫君隔河汉，凉夜月生初。"]},{"t":"寄慈溪普天泽监县","f":"五言律诗","c":["闻说慈溪县，官闲地更偏。","两潮来海错，六月刈山田。","晓塔天童寺，春帆日本船。","何时琼树底，花夕醉婵娟。"]},{"t":"秋夜杂咏三首 其一","f":"五言律诗","c":["对酒不能饮，灯前笑又悲。","转头都觉谬，对面莫相疑。","白发无休日，青天有坏时。","微酣且熟寐，一任老夫痴。"]},{"t":"秋夜杂咏三首 其二","f":"五言律诗","c":["平居在城市，无梦傍江湖。","世事有今日，生年犹故吾。","检书逢越绝，引曲感吴趋。","邻叟邀皆醉，归来不用扶。"]},{"t":"秋夜杂咏三首 其三","f":"五言律诗","c":["世俗今多事，人心此一时。","风尘吾道在，江海我生悲。","白日终难系，青山不可移。","吾方饮吾酒，君自着君棋。"]},{"t":"赋林泉民","f":"五言律诗","c":["群居傍城郭，独汝向林泉。","乱世知谁在，荒村只自怜。","白云栖晚树，流水界秋田。","亦有催租吏，敲门横索钱。"]},{"t":"和谢雪坡太守东阡道中二首 其一","f":"五言律诗","c":["上相深求治，明公独爱民。","三江不用武，两郡且行春。","陇麦连村好，池秧得雨频。","数州飘泊者，来此避风尘。"]},{"t":"和谢雪坡太守东阡道中二首 其二","f":"五言律诗","c":["淮楚纷纷际，谁怜老逸民。","一为吴郡客，三见洞庭春。","世路间关久，侯门接纳频。","麻衣犹似雪，不敢涴缁尘。"]},{"t":"寄愚隐智东堂","f":"五言律诗","c":["落日太湖上，归舟又碛沙。","百年同是客，两寺即为家。","老竹仍多笋，枯藤也自花。","何时结茅屋，相伴老烟霞。"]},{"t":"垂虹亭晚坐","f":"五言律诗","c":["长桥戎马后，旂帜尚纷纷。","吴越东西隔，江湖左右分。","荒哉皮学士，去矣范将军。","谁种千头橘，空山卧白云。"]},{"t":"送陶教授","f":"五言律诗","c":["乱世兵犹满，崇文礼自宽。","青云总朝士，白发且儒冠。","苜蓿先迎日，皋比不受寒。","娄江足双鲤，好好寄平安。"]},{"t":"舟中昼寝","f":"五言律诗","c":["篷窗坐春雨，偏与睡相宜。","襆被支头稳，茶瓯破梦迟。","昔年为客惯，今日觉吾衰。","无限沧洲意，令人有所思。"]},{"t":"送叶以诚归金华","f":"五言律诗","c":["乱世兵虽满，吾儒气自伸。","黄金赠说客，白璧聘从人。","念子真才俊，嗟余岂隐沦。","向来稽古学，留以奉君亲。"]},{"t":"题庆云东竹水居","f":"五言律诗","c":["水光当户白，竹色上衣青。","风露涵虚室，江湖入净瓶。","林梢闲挂锡，月影静翻经。","止观何闻见，秋声出杳冥。"]},{"t":"秋日游虎邱逢径山元上人","f":"五言律诗","c":["黄叶树层层，兹游记昔曾。","到山疑是梦，出寺忽逢僧。","短簿荒祠酒，生公旧塔灯。","留诗骇浮俗，山鬼也多能。"]},{"t":"寄安国长老慈云谷","f":"五言律诗","c":["慈公卓锡处，台殿旧经行。","恶竹何多俗，孤松只自清。","步回春雨作，定起夜潮生。","我亦逃禅者，山林老弟兄。"]},{"t":"以张仲举韵送毅景中任长芦寺二载诗就答仲举 其一","f":"五言律诗","c":["被旨辞京阙，还家复远途。","行吟头戴笠，趺坐膝穿芦。","佛国传宗镜，王门得衬珠。","西来祖师意，先尔设伊蒲。"]},{"t":"以张仲举韵送毅景中任长芦寺二载诗就答仲举 其二","f":"五言律诗","c":["吾亦怜吾竹，萧然只数竿。","多生遗病俗，独汝觉心安。","五月秋声早，千山雨气寒。","裁诗谢张祜，岁晚好相看。"]},{"t":"送李斯立","f":"五言律诗","c":["南国风尘满，西江道路难。","乡人问家信，津吏识儒冠。","短发何由黑，孤心只自丹。","放歌聊纵酒，努力且加餐。"]},{"t":"次韵雪诗","f":"五言律诗","c":["闭门三日雪，竹外转萧然。","夜色侵书幌，春寒压篆烟。","诗题名彦后，酒让老夫先。","一个袁高士，风流五百年。"]},{"t":"登灵岩山","f":"五言律诗","c":["木杪见浮图，盘盘一径迂。","倚岩留客坐，过岭倩人扶。","野色平如削，湖光澹欲无。","残碑不可读，春草没双趺。"]},{"t":"送澄上人游浙东 其一","f":"五言律诗","c":["浙水东边寺，禅房处处佳。","千崖无虎豹，二月已莺花。","晓饭天童笋，春泉雪窦茶。","烦询梦堂叟，面壁几年华。"]},{"t":"送澄上人游浙东 其二","f":"五言律诗","c":["浙水西边寺，天寒子独经。","雪山当户白，云树入湖青。","虎迹泉头见，猿声石上听。","俊公中立坐，烦尔候禅扃。"]},{"t":"向游武林之龙井过南天竺登二老亭曾赋二诗","f":"五言律诗","c":["二老题诗处，风流不再逢。","客归黄叶雨，僧住白莲峰。","谁谓山无凤，人传井有龙。","白头江海上，今夕寄行踪。"]},{"t":"三月二十五日过上洋十六保徐居士柯庄二首 其一","f":"五言律诗","c":["野水明春色，晴沙带汐痕。","朱楼黄鸟日，青草白鹅村。","野老能分席，官军不到门。","毋烦问渔艇，即此是桃源。"]},{"t":"三月二十五日过上洋十六保徐居士柯庄二首 其二","f":"五言律诗","c":["趁潮深入港，风急水西流。","沙润轻沾屐，桥低欲碍舟。","孤花馀晚艳，芳草乱春愁。","沙鸟应相笑，衰年尚远游。"]},{"t":"四月十三离上洋回华亭","f":"五言律诗","c":["垂老重来此，临分即惘然。","云吞隔浦树，潮打送风船。","卜筑虚求地，行藏欲问天。","淮南兵革后，荒却种瓜田。"]},{"t":"送张可道赴嘉定府太守","f":"七言古诗","c":["秦中百二汉关河，曾见乘骢旧所过。","栈道地形天下险，嘉州风物古来多。","分符又叶三刀梦，入境先闻五裤歌。","父老扶筇亲引导，将军负弩疾撝诃。","锦袍错落金为带，白马联翩玉作珂。","兴学固当崇俎豆，防边还为戢干戈。","四川画省劳询问，一郡苍生望抚摩。","楼倚青溟来万景，山横紫翠接三峨。","题书别馆鱼堪寄，退食公堂雀可罗。","西蜀考功当第一，他山有石为君磨。"]},{"t":"题周伯温待制为苏老人篆七十古来稀有字后","f":"七言古诗","c":["天上词臣小篆书，方今端合比琼琚。","肯将南极仙人寿，题向东窗隐者居。","玉屑露凝金错落，锦茵春暖绣芙蕖。","缠腰信有扬州鹤，垂钓宁无渭水鱼。","方士曾分烧药火，诸孙亲御看花车。","黄金意气留宾客，白发风神照里闾。","世上虚名皆寄尔，人生此乐复何如。","芝兰香里浑如画，百岁传家庆有馀。"]},{"t":"赠六合县宣差伯士宁因兵乱于滁泗之间独县境肃然作诗以叙其实","f":"七言古诗","c":["风尘千里暗淮堧，六合孤城独晏然。","保障正符明主意，歌谣争颂长官贤。","公庭吏散门如水，驿馆宾来酒似川。","疏水为湟成重地，返风灭火动皇天。","军需会计多雄略，兵卫森罗总少年。","兴学未闻忘俎豆，防边仍见戢戈鋋。","编民辟地增输赋，远客移家愿受廛。","封壤远连瓜步外，妖氛不到瓦梁边。","鱼盐山市宵鸣柝，米麦江桥晓泊船。","十邑自今称第一，前程谁谓隔三千。","王纲政尔关明教，民瘼何人解倒悬。","舆论已传霄汉上，丰碑立在县衙前。"]},{"t":"送王君宝佥宪调河南道","f":"七言律诗","c":["广陵城下送轺车，贱子无由奉尺书。","南峤几年仍盗贼，中原千里半邱墟。","天闲岂少追风骑，人海犹多漏网鱼。","素有澄清天下计，更须抗疏动乘舆。"]},{"t":"寄芊希曾","f":"七言律诗","c":["白发镜中添几茎，江空岁晚可怜生。","千金有人市马骨，一饭何处无鱼羹。","东家娶妇夜宴客，北里送子春朝京。","年当五十不得意，目送飞鸿生远情。"]},{"t":"道士胡道元常以一舟往来洪之东湖其自扁有曰活死人窝为赋此","f":"七言律诗","c":["一住行窝几百年，蓬头长日走如颠。","海棠亭下重阳子，莲叶舟中太乙仙。","无物可离虚壳外，有人能悟未生前。","出门一笑无拘碍，云在东湖月在天。"]},{"t":"赠数学王隐居","f":"七言律诗","c":["青囊曾阅五行书，客亦还知此理无。","太古以前无甲子，先天之后有尧夫。","鸟官当日才司历，龙马于今又出图。","馀子未能通许事，黄金只可说荣枯。"]},{"t":"题赤壁图","f":"七言律诗","c":["赤壁矶头秃鬓翁，兴来携酒泛秋风。","偶论水月盈虚际，并入江山感慨中。","华发多情伤老大，皇天无地着英雄。","神游八极知何许，良夜应骑一鹤东。"]},{"t":"吴中五日追念故友李时中李钦嗣有感而作为时中生忌","f":"七言律诗","c":["梦绕南冈北岭云，一杯无计洒松筠。","世间我岂长贫者，地下君为不死人。","夜雨自荒张祜宅，秋风谁障庾公尘。","于今友道俱凋丧，落日江湖泪满巾。"]},{"t":"八月十六日送张仲举至秦邮驿是夕邵文卿置酒云峰台望月二首 其一","f":"七言律诗","c":["水驿官船晚未开，月明乘兴且归台。","扬州鹤怨山人去，甓社珠迎国士来。","千里何时重命驾，百年今夕此衔杯。","同君尽醉交游地，为问秦郎安在哉。"]},{"t":"海上即事","f":"七言律诗","c":["范时港头生事微，三月海上行人稀。","东沙西沙海不熟，大信小信舟当归。","护巢野鹊并枝立，得食水禽何处飞。","无鱼换酒亦谩尔，只恐丁男荒钓矶。"]},{"t":"送解伯中赴史馆召至正癸未朝廷以史事遣使起河东张先生于广陵明年史局开又于广陵徵解先生广陵连有二盛事睹兹荣美赋诗为别","f":"七言律诗","c":["海岳澄清又百年，前朝陈迹散云烟。","恭闻天上修三史，连向淮南起二贤。","青简旁搜成大典，黄华迭出购遗编。","先生善用春秋法，岂下当时太史迁。"]},{"t":"送陈景川归盱眙","f":"七言律诗","c":["第一山中风物殊，我欲买田来卜居。","风林把酒听黄鸟，雪港挂罾分白鱼。","富贵不来吾老矣，渔樵有约子何如。","可能久作终焉计，北海方修荐鹗书。"]},{"t":"虎溪三笑图","f":"七言律诗","c":["三老风流笑口开，山中猿鹤亦惊猜。","攒眉入社谩多事，送客过溪能几回。","僧影欲随秋水去，虎声偏傍石桥来。","东林绝响今千载，抚卷题诗愧乏才。"]},{"t":"寄张仲举助教","f":"七言律诗","c":["三寄新诗竹下来，多君高兴忆东淮。","尘埃没马昏归舍，风雨听鸡晓入斋。","此日阳城须谏议，当时方朔谩诙谐。","曼曼花底相思夜，酒满春城月满街。"]},{"t":"寄拔实尚书","f":"七言律诗","c":["忆陪冠盖集通津，下士无由拜后尘。","曾和淮南招隐曲，得从天上谪仙人。","鹓鸾在列谁堪并，鸿鹄高飞不可驯。","遥想退朝香满袖，题诗还记竹轩春。"]},{"t":"送李子威赴国子监时康鲁瞻亦除监司业","f":"七言律诗","c":["曾占龙头第一名，先生元是监诸生。","楼船近向淮南发，驿骑虚从颍上迎。","宣室几年无贾谊，谏垣今日有阳城。","同寅更得同年者，同振斯文答圣明。"]},{"t":"二月十一日祭长男之墓","f":"七言律诗","c":["三岁女孙方学行，牵衣随母上新坟。","青春过眼少晴色，白发向人唯哭声。","醉里狂歌聊自适，梦中相见只如生。","他年何处藏吾骨，不尽人间父子情。"]},{"t":"寄乌古孙干卿参议","f":"七言律诗","c":["紫宸奏对出班行，画省论思昼漏长。","三月不知烧笋味，一春还忆煮茶香。","几人白发黄花酒，何处青山绿野堂。","扶植皇纲在今日，中原草木仰辉光。"]},{"t":"上清卢道士所藏双龙图","f":"七言律诗","c":["仙潭烟雾晚冥冥，彷佛飞空剑气腥。","岩穴几年当蜕骨，画图今日露真形。","天瓢水浅阴犹伏，宝藏云深夜不扃。","好就卢敖听驱使，八方行雨鼓风霆。"]},{"t":"夜思","f":"七言律诗","c":["斗帐方床一布衾，睡馀推枕复长吟。","青灯细雨三更梦，白首残编万古心。","天上不知何岁月，城中谁信有山林。","哀歌坐待东方白，短发刁骚不满簪。"]},{"t":"萧万户野鹤卷子","f":"七言律诗","c":["肯著边尘浣缟衣，当时城郭是耶非。","自离碧海三山去，直过青城万里飞。","老去扬州空逸兴，何人沙苑脱危机。","丈夫功在麒麟阁，莫说仙家有令威。"]},{"t":"和孟景章秋雨见寄","f":"七言律诗","c":["十日空斋风雨阴，闭门唯计作诗淫。","屋茅新补一重厚，池水又添三尺深。","爨下家童耽熟睡，灯前山鬼听哀吟。","知君剪烛方酣饮，肯信幽人独苦心。"]},{"t":"柬句曲外史张伯雨","f":"七言律诗","c":["霞佩翩翩出洞天，当时彷佛见癯仙。","几年南国张公子，今日西湖葛稚川。","沧海尘飞丹已熟，玉堂人去榻空悬。","林间载酒来相觅，乞写仙经与世传。"]},{"t":"送干克庄佥宪调淮西道","f":"七言律诗","c":["绣斧煌煌拥使舠，才名奕奕在中朝。","甘泉词客河东赋，蓬岛仙人海上樵。","风振紫山迎驿骑，云开金斗见秋雕。","澄清事业须公等，桂树淮南未易招。"]},{"t":"赠松江知事唐景友三月二十八日同茅子刚府判郭宗唐推官同日上官","f":"七言律诗","c":["三月云间同上日，理官判府总英髦。","香风又动红莲幕，雨气微侵白苧袍。","刺史燕居邀论事，掾郎鹄立看挥毫。","衰翁亦是淮南客，拭目青霄望尔曹。"]},{"t":"送谷君王都事赴南台御史","f":"七言律诗","c":["几年坐啸元戎幕，一日来簪御史冠。","已有声名惊海内，更须风采动朝端。","星明使节三台近，霜落江城六月寒。","应救倒悬如水火，东南民力正艰难。"]},{"t":"题王可道同知濯缨亭","f":"七言律诗","c":["翛然无限沧浪意，况有幽亭近水安。","孺子有歌同鼓枻，故人无约共弹冠。","通宵云气侵衣润，六月波光入坐寒。","惭愧东华尘土客，知谁来此一凭栏。"]},{"t":"同诸公游西城木兰院","f":"七言律诗","c":["三月西城风日好，短筇随意踏晴沙。","王孙不识蘼芜草，童子来寻枸杞芽。","白发有人中卯酒，清泉无火煮春茶。","山扉寂寂僧归晚，落尽辛夷一树花。"]},{"t":"送陈子山状元赴太庙署令","f":"七言律诗","c":["天上词臣锦作裳，喜趋清庙奉蒸尝。","宝刀刻颂登彝鼎，金砚挥毫撰乐章。","太液秋风黄鹄下，斋房明月紫芝香。","礼成月荐应分胙，彩服承恩到北堂。"]},{"t":"广陵岳宫醮夜观王澹渊高士蒇事自登瀛桥而迎师入黄箓坛","f":"七言律诗","c":["濛濛云气湿霓旌，小队红绡凤蜡明。","鸾鹤舞随行道影，鱼龙出听步虚声。","淮南高士青毛节，句曲仙人碧玉笙。","一路天风吹不断，此身今夕在蓬瀛。"]},{"t":"送董运使之江西参政","f":"七言律诗","c":["煌煌渭节拥麾幢，父老曾期镇此邦。","合上星辰朝北阙，且携霖雨过西江。","侯门何啻朱轮十，相业今看白璧双。","嗣见丰碑书盛美，玉堂端有笔如扛。"]},{"t":"送杨士先归长安","f":"七言律诗","c":["落魄麻衣不受尘，黄金挥尽只清贫。","新丰市上酒濯足，韦曲城南花恼人。","豪杰谩嗤秦逐客，渔樵能话汉功臣。","清时未老丹心在，且把长竿钓渭滨。"]},{"t":"九月十日自寿","f":"七言律诗","c":["余生堪叹复堪怜，喜际明时老市廛。","把菊已从前一日，种桃犹待后千年。","但令有子亲书帙，莫怪无人送酒钱。","寡欲清心今得矣，炼丹何用学神仙。"]},{"t":"送王君章掾史侍司众丞督办河防竹木还京","f":"七言律诗","c":["方今禹稷际昌期，河水横流适在兹。","十七万人重浚日，三千馀岁再清时。","相君功德邱山重，天使声名草木知。","为送大农王掾史，小儒歌诵入新诗。"]},{"t":"送将作同知明斋趣河防竹木事还京","f":"七言律诗","c":["明公端有济川才，百役供需入总裁。","东海神鞭驱石去，南山材木蔽江来。","万年砥柱狂澜息，千里桑麻故道开。","昭代君臣同禹稷，直将和气弭天灾。"]},{"t":"赋崧碧为丁贞夫廉使寿","f":"七言律诗","c":["崧高雄奠白云乡，石势参差面洛阳。","地涌两山通上界，天开四岳拱中央。","丹邱炼药交龙虎，子晋吹笙引凤凰。","自是勋名同不朽，千年岩壑有辉光。"]},{"t":"阮子华所藏桃源图","f":"七言律诗","c":["桃源流水似天台，彷佛三生到此来。","玉杵玄霜无处觅，金堂玉室为谁开。","沧州一夜生芳草，阴洞千年长绿苔。","何必诳人秦甲子，渔人祗见两三回。"]},{"t":"题泰州赵子威太守平反王㽘冤狱之事是时赵子威适除翰林待制","f":"七言律诗","c":["㽘也衔冤谁与雪，明公公议动乾坤。","狂澜既倒回中砥，白日高悬到覆盆。","一代简书称折狱，百年冠盖见高门。","承恩又上金銮去，万岁千秋奉至尊。"]},{"t":"送芊希曾入江西宪","f":"七言律诗","c":["岸柳汀花几送迎，买舟谁信客囊轻。","真金百炼色不改，宝瑟再调声更清。","直气犹能唾奸佞，苦心宁肯负公卿。","间关世道谙应熟，终保乌台好姓名。"]},{"t":"寄庵诗为余寄庵作","f":"七言律诗","c":["此身江海即蜉蝣，小住庵中五百秋。","万劫有穷唯道在，八方无碍与天游。","虎龙夜合黄金鼎，鸾鹤朝飞白玉楼。","暂向世间忘尔汝，一瓢春酒肯相留。"]},{"t":"岳宫登瀛桥","f":"七言律诗","c":["叠石为桥跨两涯，只如平地入烟霞。","银河夜掷仙人杖，碧海秋横奉使槎。","浴水先迎三岛日，隔阑遥看十洲花。","月中时有箫声过，多是山头圣母家。"]},{"t":"天长县长伯颜祈雨适见白龙有感","f":"七言律诗","c":["六月天长旱为虐，颜侯夙夜最忧农。","丹心贯日回玄象，赤脚登山起白龙。","雷驭电光惊不定，岳灵云气出相从。","斯民已作商霖望，吉梦何时到九重。"]},{"t":"题山居图","f":"七言律诗","c":["石子坡头松两株，水光岚气护幽居。","山翁被酒爱骑马，溪友放船来捕鱼。","秋色自随黄叶老，野怀常共白云舒。","何时卜筑如图画，竹下开轩更读书。"]},{"t":"寄题上清钟秀楼","f":"七言律诗","c":["钟秀楼成天下稀，象山弋水相因依。","烟云显晦出奇观，草木动荡流清辉。","常闻仙人骑鹤至，亦有隐者乘风归。","吾将从之一榄结，目送秋江鸿雁飞。"]},{"t":"瑞雪为刘芝田赋","f":"七言律诗","c":["风卷寒溪漾碧沙，晓来惊见玉横斜。","人间风日不到处，天上神仙解种花。","九地暖回龙有穴，三山云静鹤无家。","泛舟来觅芝田叟，留作山阴胜事誇。"]},{"t":"寄谢方方壶写寄遥山古木","f":"七言律诗","c":["鬼谷阴阴苔藓斑，只除猿鹤伴高閒。","丹光或在藤萝外，剑气常留水竹间。","每读内篇消永日，还将生纸写遥山。","衰翁可是无仙骨，不得相从共往还。"]},{"t":"送孙从义宪史贡部","f":"七言律诗","c":["贡名书到拆封开，政尔诸曹议选才。","侍史阁中帘影动，尚书天上履声来。","阶墀伏谒人皆喜，符牒铺张手自裁。","不有雄声惊画省，可无清论达乌台。"]},{"t":"送余廷心翰林应奉","f":"七言律诗","c":["枫叶萧萧江已秋，吴船三日住扬州。","靛花深染青绫被，云叶新裁紫绮裘。","征驿马嘶风满树，别筵人散月当楼。","明年春雁将书去，人在蓬瀛第几洲。"]},{"t":"画鱼","f":"七言律诗","c":["平生踪迹侣鱼虾，浦月山风满客槎。","曾向春盘登北鲔，更从丙穴荐南嘉。","赏花钓得留诗友，折柳穿来觅酒家。","万里江湖清梦远，于今空对画中誇。"]},{"t":"寄谢察院高德进宪史寄来杨友直书居竹轩三大字","f":"七言律诗","c":["三字封来墨未乾，堂轩舒展对琅玕。","高人不待笼鹅换，好客多从载酒看。","月夜有怀通白下，秋潮无信寄长干。","清台翠柏应千丈，静想风霜卷地寒。"]},{"t":"送李唐臣调山南宪幕","f":"七言律诗","c":["潮落寒汀水欲冰，酌君何惜酒如渑。","人怜狗监知司马，我喜龙门识李膺。","爽气九秋横楚泽，先声一日到江陵。","君行自厉青云志，赤鴳终惭九万鹏。"]},{"t":"程氏寻乐斋","f":"七言律诗","c":["当时弄月与吟风，一代高人自不同。","伊洛源头无别派，孔颜心上有全功。","岁寒只在箪瓢内，春色还归杖履中。","今日看君能到此，不须重问爱莲翁。"]},{"t":"夜泊青蒲村","f":"七言律诗","c":["黄叶飘飖秋满天，数家茅屋更翛然。","村中老人不识字，溪上小儿能驾船。","荠菜登盘甘似蜜，芦花纫被煖如棉。","此中长得无宵警，春雨扶犁学种田。"]},{"t":"河图精舍","f":"七言律诗","c":["荣河东去几迁移，抚事令人动所思。","龙马不来吾已矣，蓍龟多验汝知之。","仙坛作记高千古，精舍明经此一时。","且向程门求绝学，吟风弄月有深期。"]},{"t":"胡道元隐东湖得许旌阳铁符延瘗旧名伏蛟台道元由广陵入京赋此以别","f":"七言律诗","c":["许令宫前旧卜邻，铁符传得尚如新。","一弹指内三千仞，八百仙中勾几人。","上界风云回羽节，空江雷雨泣蛟神。","淮南他日来相访，却惜东湖借约尘。"]},{"t":"赠谈子平者","f":"七言律诗","c":["高人不见诜僧判，江海同谁讲子平。","能以静功窥造化，每于先事动公卿。","君从何处得此术，我已多时闻令名。","今夕蓬窗听清论，流年容与话平生。"]},{"t":"藏李氏拙斋","f":"七言律诗","c":["李君抱朴深居处，曲几匡床事事幽。","三穴有谋怜狡兔，一巢无计笑痴鸠。","白云生满溪前面，黄叶飞来屋上头。","应是此中藏大巧，凤楼十二要添修。"]},{"t":"春日游上方寺因过别业","f":"七言律诗","c":["今日雨晴山亦佳，散行聊复写幽怀。","田翁入郭买春酒，野衲下堂留午斋。","老去任添新白发，平生能著几青鞋。","醉中天地堪衾枕，却笑刘伶死便埋。"]},{"t":"怀方壶高士","f":"七言律诗","c":["尘湖山下足烟霞，羡尔方壶道士家。","雨后放龙耕绿野，日中呼犬试丹砂。","琼林一路芝如草，碧涧千年竹有花。","正欲相陪此深隐，半盂分我饭胡麻。"]},{"t":"赠茅山彭鍊师","f":"七言律诗","c":["坐对三峰绝俗缘，羽衣消散即神仙。","几年大洞传真箓，十日清斋读内篇。","采药每行青涧底，散花多近白云边。","精神鍊得如冰雪，妙入羲皇太古先。"]},{"t":"邱德辅明德斋","f":"七言律诗","c":["方寸纤尘一扫除，湛然澄澈只如初。","本原不昧先天理，功效多从大学书。","池上倚筇秋水净，月中挥麈夜窗虚。","修齐事业须公等，我老昏昏总不如。"]},{"t":"送人归金坛","f":"七言律诗","c":["沧洲三日北风作，海气冥冥吹去舟。","游子思亲白云舍，主人赠尔青貂裘。","沙头明月为谁好，夜半寒潮生客愁。","我亦轻装待明发，挂帆挝鼓上扬州。"]},{"t":"感时伤事寄张仲举博士","f":"七言律诗","c":["边报纷纷日转频，彭城犹未息风尘。","中原白骨多新鬼，浮世黄金少故人。","阮籍一生唯纵酒，季鹰今日定思莼。","河东鹤叟应相忆，落日悲笳泪满巾。"]},{"t":"白云轩为罗氏赋","f":"七言律诗","c":["太行山上思亲日，句曲峰前写兴时。","千古风流无处觅，一般意味少人知。","归来远道何堪赠，老去閒心只自怡。","怅望碧天还欲暮，令人空拟惠休诗。"]},{"t":"挽吕州判","f":"七言律诗","c":["七秩高年古亦稀，考之终命见天机。","岳阳湖上神仙过，舍卫城中长者归。","门第预题新墓表，几筵犹设旧朝衣。","青山埋骨知何处，落日沧江望鹤飞。"]},{"t":"题上海天妃宫因见王元吉壁间所题诗次韵二首伤今感昔情见于辞 其一","f":"七言律诗","c":["昔年漕运开洋日，御赐香来动杳冥。","真箓九朝连昼夜，斋厨一月断荤腥。","祠光赤现天妃火，云气黄占使者星。","沉璧丽牲严祀典，至今神肃在宫庭。"]},{"t":"题上海天妃宫因见王元吉壁间所题诗次韵二首伤今感昔情见于辞 其二","f":"七言律诗","c":["何年立庙对沧溟，合殿濛濛紫雾冥。","香暗水仙毛发古，剑留山鬼髑髅腥。","寝楼下瞰扶桑日，饷道遥连析木星。","圣代祝釐频遣使，徽音不日下宫庭。"]},{"t":"次李希颜述怀韵","f":"七言律诗","c":["八月边声草木寒，愁来短发不胜冠。","诸公莫诮王夷甫，我辈终惭管幼安。","酒券如山空好客，田毛何日再输官。","兰陵沟上松无恙，还有孤猿夜夜看。"]},{"t":"登狼山醉题僧壁","f":"七言律诗","c":["白狼山头僧卓庵，我蹑飞履穷幽探。","麻姑又见海清浅，女娲不补天东南。","危枝如龙固矫矫，怪石似虎犹耽耽。","兴来提笔写狂语，此身只合栖云龛。"]},{"t":"题朱伯礼西村草堂","f":"七言律诗","c":["爱汝西村之草堂，嚣尘不到堂中央。","夕阳欲下山更好，大火未流夜已凉。","二履也能来户外，小舟即遣系篱傍。","岂无百榼扬州酒，与子同吃歌《沧浪》。"]},{"t":"白云上人悼章","f":"七言律诗","c":["八十七翁如古佛，山房只共白云居。","一闻东土传来法，三校西天译后书。","劫火不烧红舍利，冰池重长碧芙蕖。","青城今夜白眉月，似汝招摇出大虚。"]},{"t":"次俞绍堂见赠诗韵","f":"七言律诗","c":["幽居地僻人稀到，闭户长歌复短歌。","红树也知秋老矣，青山不到客如何。","茫茫天地凉风急，渺渺江湖夜雨多。","淮泗数州消息断，只除征雁度关河。"]},{"t":"笠泽同倪云林王伯纯饭散过大姚江舟中赋","f":"七言律诗","c":["大姚江头风乍稀，小陆宅前人独归。","霜枫红于大药染，沙鸟白似孤云飞。","持螯把酒一生足，食蛤踞龟千劫非。","雪滩水落独无恙，肯借老夫为钓矶。"]},{"t":"送夏君美宪使出使回浙","f":"七言律诗","c":["三入军中只布衣，至今颜面带霜威。","中原定乱刘琨老，南粤称臣陆贾归。","走也暮年空感慨，使乎今日有光辉。","乾坤始觉王纲正，夜夜星台拱太微。"]},{"t":"寄冯仁伯","f":"七言律诗","c":["七十老为吴郡客，故人不必问馀生。","清尊日饮尚一斗，黑发晨梳犹几茎。","藏骨谩思淮上去，移家犹望越中行。","他年或有相逢地，可得同君睹太平。"]},{"t":"次曹新民感时伤事韵三首 其一","f":"七言律诗","c":["岁晚霜风裂弊裘，剑歌谈麈一生休。","牵萝不补山中屋，挂席将归海上洲。","月夜拂弦弹白雪，春朝携酒看丹邱。","风流谁似曹公子，华发不知人世愁。"]},{"t":"次曹新民感时伤事韵三首 其二","f":"七言律诗","c":["北伧老作江南客，抚卷令人百感生。","天下纷纷何日定，胸中磊磊有时平。","沧江日映旌旗影，紫塞风悲鼓角声。","今日封侯总年少，老来豪气谩峥嵘。"]},{"t":"次曹新民感时伤事韵三首 其三","f":"七言律诗","c":["客来为说淮南事，白骨如山草不生。","翻覆几回云雨手，登临无限古今情。","长街竟日人烟绝，小市通宵鬼火明。","欲省先茔归未得，悬河老泪若为倾。"]},{"t":"蔡大掾乃翁八十寿","f":"七言律诗","c":["蓬莱山下老仙翁，却隐吴门水竹中。","生世几逢尧甲子，高风不减汉申公。","绣衣坊里诸郎贵，绿酒尊前一笑同。","我亦行年方七十，几时相约问崆峒。"]},{"t":"过吴江华严寺赠断云讲主","f":"七言律诗","c":["断云老僧如断云，无心舒卷自氤氲。","空山与之结为侣，远道也堪持赠君。","黑夜雨从龙听法，青天风引鹤同群。","江湖我亦忘机者，半榻今宵喜见分。"]},{"t":"宿宁境寺","f":"七言律诗","c":["三月江南访积翁，故人同约向山中。","百年刺促何为者，一日高閒不负公。","斋阁对床听夜雨，茶堂趺坐足春风。","雪滩借地容吾隐，来往扁舟与子同。"]},{"t":"王仲沔佥事隐居上虞之东山闻航海北山作此以寄","f":"七言律诗","c":["鉴湖春水暖生波，几个归航载酒过。","掩鼻东山将不免，伤心南浦竟如何。","纷纷白发交情在，耿耿丹心老泪多。","安得相从天上去，玉堂清夜听鸣珂。"]},{"t":"过碛沙延寿寺入游赠毅刚中长老","f":"七言律诗","c":["费家洲上元公塔，又见前身示见时。","舍利放光成五色，牡丹分供作千枝。","法门总是西来意，经藏兼传古注诗。","文笔峰前松树下，瓮书藏得待吾师。"]},{"t":"送韩致用之温州教授","f":"七言律诗","c":["祖帐倒馀双玉尊，轺书催发五云门。","喜为太府诸侯客，犹是前朝宰相孙。","讲座昼闲书满屋，学田秋熟稻盈村。","遥应东壁图书府，迟子抽毫共讨论。"]},{"t":"韩致用梦鹤","f":"七言律诗","c":["畴昔相过赤壁矶，神交遗思尚依依。","应从五色云中过，还绕三株树上飞。","月色满庭空夜帐，露华如雨湿秋衣。","蓬莱山下花无数，迟子吹箫作伴归。"]},{"t":"题韩致用五云书屋次程以文郎中韵","f":"七言律诗","c":["看山不出草堂门，门返萧萧是白云。","隐几松风生鹤梦，卷帘秋水爱鹅群。","坐开句曲仙人酒，起读临川太史文。","后夜柁楼乘月色，贺家湖上拟寻君。"]},{"t":"宁境寺涵碧轩","f":"七言律诗","c":["老衲筑轩湖上头，半间曾借数宵留。","窗迎紫翠千峰月，帘捲玻璃万顷秋。","别浦暝时迷远树，沧洲明处见飞鸥。","定回坐待波澜静，一点珠光夜不收。"]},{"t":"题张德长草堂二首 其一","f":"七言律诗","c":["屋下清泉屋上山，独馀猿鹤伴高闲。","仙家只在松萝外，海月常悬水竹间。","社瓮今朝村酿熟，邻翁何处棹歌还。","华阳真逸时相觅，闻道岩扉夜不关。"]},{"t":"题张德长草堂二首 其二","f":"七言律诗","c":["高人自爱山居好，绕舍清溪带雪沙。","浮玉峰前常作客，句金坛下即为家。","仙人未采芝如草，令尹将归菊有花。","他日常良分半席，白头同汝老烟霞。"]},{"t":"挽卞隐君二首 其一","f":"七言律诗","c":["持杯前日送官航，返袂今朝哭寝堂。","乱世几人全白骨，他山何处凑黄肠。","铁冈路杳空秋草，金卤亭荒自夕阳。","有子归来印如斗，却招魂气返家乡。"]},{"t":"挽卞隐君二首 其二","f":"七言律诗","c":["死别那堪属乱离，乡人闻讣总含悲。","家留南国孙何恃，路隔中原子未知。","石椁衣衾藏夜壑，漆灯风雨泣秋帷。","西风执绋胥门路，无限伤心涕泗垂。"]},{"t":"寄吴江塔院断云讲主","f":"七言律诗","c":["华严杖室老维摩，愿力新来示疾多。","不假医王加守护，毋烦天女问云何。","空花境界离诸妄，宝梵音声散百魔。","海印堂中狮子座，尚容参请重相过。"]},{"t":"寄申屠子迪佥宪","f":"七言律诗","c":["先生旧德在甘棠，故老争留住草堂。","湖上月明鸥鹭熟，山中雨过蕨薇香。","数茎白发终难变，一日丹衷不可忘。","出处独翁全大节，千年青史有辉光。"]},{"t":"冯安道提举挽章","f":"七言律诗","c":["白发交游共七旬，翩然长逝独伤神。","中原朝士无多传，太学诸生复几人。","旧业已荒吴郡宅，新阡还与范公邻。","伊谁杰笔书潜德，一束生刍泪满巾。"]},{"t":"奉简张天民有道先生","f":"七言律诗","c":["令子已为吴县尹，先生犹是葛天民。","春秋七十又八岁，江海百年能几人。","多士问奇加束脯，诸孙供馔砍鲜鳞。","荆溪旧业知无恙，白鹤时来送喜频。"]},{"t":"寄崔宗文","f":"七言律诗","c":["白发无家七十翁，一枝竹节尚西东。","不因避地来吴下，正爱看山入剡中。","台阁故人书信少，江湖狂客酒船空。","老怀无限平生意，清话何时一夕同。"]},{"t":"寄王左丞","f":"七言律诗","c":["锡谷三山霖雨开，筹边须仗济时才。","行兵暗与孙吴合，论道多从董贾来。","太府上功金作印，高堂称寿玉为杯。","将星夜夜明如月，独向中天拱上台。"]},{"t":"吴江华严寺西轩洗竹因赋诗一首","f":"七言律诗","c":["华严寺里断云师，许我来题洗竹诗。","未论竿头能进步，且教节外莫生枝。","定回独夜秋声减，经罢西轩暝色迟。","从此一尘无染著，岁寒唯有此君知。"]},{"t":"春日同王仲远偕游松林湖之上西望洞庭东西两山是日寒食有感","f":"七言律诗","c":["湖上春来数往还，乱中宁放老夫閒。","一百五日又寒食，七十二峰非故山。","行李只留诗卷在，落花应怪酒杯悭。","竹西拜扫知何日，目断归鸿夕照间。"]},{"t":"戊戌年避地吴门九日感怀","f":"七言律诗","c":["行年七十犹为客，何处江湖着老夫。","黑发空存数茎在，黄花也笑一钱无。","家徒活计如鸠拙，病起形容似鹤癯。","独把茱萸仍独酌，酒酣不用阿孙扶。"]},{"t":"寄谢太守","f":"七言律诗","c":["君侯夙夜爱民心，槜李重开颂好音。","兵后州人无菜色，乱馀厅事有棠阴。","熊轓按部兵车息，燕寝凝香画戟深。","走也门墙老宾客，尚哦云月在山林。"]},{"t":"河南陆思颜两举不第隐于南浔以医卜治生作诗赠之","f":"七言律诗","c":["长歌放浪江湖上，一个青囊肘后悬。","但见王门多将相，焉知市井有神仙。","折蓍独出先天后，用药谁从未病前。","自笑区区无一技，哦诗乞米度衰年。"]},{"t":"寄山阴天章寺静默堂长老","f":"七言律诗","c":["昨日相从访了翁，妙高台上数宵同。","十年秪在分阴里，万法都归一默中。","扬子江山仍落照，越王城郭又西风。","阿师说法天章上，开遍人间色与空。"]},{"t":"赠李左丞","f":"七言律诗","c":["手分云汉下天津，一洗江淮战伐尘。","紫气独行周柱史，白衣谁识李山人。","铺陈礼乐三千字，保障东南亿万民。","戡定成功在今日，未容归卧五湖春。"]},{"t":"贺王彦诚新除授浙江省左丞之命","f":"七言律诗","c":["南省新堤已筑沙，禁城犹是旧京华。","山中未识将军树，天上新颁宰相麻。","紫电青霜开武库，金符玉节拥高牙。","东南定乱成功了，四海车书共一家。"]},{"t":"送吴志学通州帅府副元帅","f":"七言律诗","c":["立马狼山最上峰，青天白日见英雄。","防边肯发屯田计，富国兼收煮海功。","烽火连营平野北，楼船酾酒大江东。","干戈八载天应厌，笑挽扶桑早挂弓。"]},{"t":"送沈玉泉书药舟","f":"七言律诗","c":["一舸宽于一亩宫，两溪无处不春风。","遥知篷下观书者，即是壶中卖药公。","啸隔沧洲声似虎，丹藏别室气如虹。","平生悔不谋深隐，蓑笠何时与子同。"]},{"t":"三月十五陪乌本初同佥李希颜祭余廷心大参于断崖因赋是诗以约明年更祭云","f":"七言律诗","c":["七年苦战守孤城，食尽无人发救兵。","诸将赴河同日死，万家嚎地几人生。","中台星拆天应泣，大节堂空鬼亦惊。","国难未平公已往，临风西望泪纵横。"]},{"t":"海陵钱文宪母汪节妇卷后","f":"七言律诗","c":["白发孀居丧乱中，苦心仍与柏舟同。","事夫在昔如宾礼，教子于今有父风。","麻枲服劳忘夜寝，粢盛供给愿年丰。","男儿饿死浑闲事，抚卷题诗意未穷。"]},{"t":"寄兴圣寺琦元璞长老兼简黄庭英知事","f":"七言律诗","c":["太息衰年七十强，经旬留宿赞公房。","上堂也趁阇黎饭，入阁仍分般若汤。","华渚虹霓生雨气，法筵龙象识天香。","遥知今夕南湖月，谁与郎官共晚航。"]},{"t":"题茅子刚虚白斋","f":"七言律诗","c":["青袍朝士斋居处，一扫淄尘万虑忘。","四壁东西凝雪色，八窗晓夜发天光。","茅君为尔传宗旨，庄子由来止吉祥。","有客坐驰空热恼，不知此地有清凉。"]},{"t":"贺顾克善授平江经历","f":"七言律诗","c":["吴门五月看除目，喜见郎君好姓名。","画省故人持酒送，黄堂太守下车迎。","百年治道随天运，一代人才出旦评。","上相忧民何以报，会将新政致升平。"]},{"t":"寄杨子尊圣寺处厚子元上人","f":"七言律诗","c":["不出空山复几年，衲衣草座独安禅。","别峰行道诸天上，善月翻经古佛前。","兵后佳期何日共，春来妙句有人传。","三生彷佛当相识，目送孤鸿落照边。"]},{"t":"赠谢太守除杭州","f":"七言律诗","c":["朝廷遣使航东海，万里南来送玺书。","着屐登山良不恶，分符典郡复何如。","李苏事业千年后，吴越封疆百战馀。","今日养民方急务，肯将徵算及舟车。"]},{"t":"寄蔡彦文掾史","f":"七言律诗","c":["凤凰池上神仙吏，却是中郎几叶孙。","幕下岂无奇计出，床头犹有异书存。","防秋列寨山如戟，蒸土为城铁作门。","何限民间可忧事，老怀那得与君论。"]},{"t":"奉答道林书记二首 其一","f":"七言律诗","c":["何年飞锡度江城，林下相逢眼倍明。","老子岂能知药性，阿师宁独擅诗名。","江风满座筼筜合，石雨侵墙薜荔生。","莫把旧家无孔笛，月明吹作凤凰鸣。"]},{"t":"奉答道林书记二首 其二","f":"七言律诗","c":["狮子林中夙夜缘，杖藜来往意方坚。","白莲社友须元亮，金粟如来是谪仙。","净梵六时严戒律，长斋十日断荤膻。","翛然古竹长松下，还许山僧醉后眠。"]},{"t":"和南宗上人高韵就呈可庭山主诗","f":"七言律诗","c":["老去喜逢方外友，一庵潇洒阖闾城。","野猿挂树窥行道，山鸟当窗候出鸣。","空界可能容我醉，新诗一复见君情。","维摩示疾今朝起，拭目街头看太平。"]},{"t":"送陈性之昆山从事","f":"七言律诗","c":["只将从事写前衔，省檄封来自拆缄。","六案更须劳彩笔，一官犹未换青衫。","风生海市朝持酒，日落江城暮卸骖。","我未识君空怅望，恍如烟水隔仙凡。"]},{"t":"题金太医杏林诗卷","f":"七言律诗","c":["董奉仙居不可寻，君家种杏亦成阴。","禁方传后龙归洞，嘉果生时虎守林。","不厌邻翁来乞药，每留渔父坐听琴。","年年二月花如海，应是先生树德深。"]},{"t":"奉题王左丞卧云轩","f":"七言律诗","c":["东山云气尽溶溶，左辖高居第几重。","玩世也为庄叟蝶，济时仍起武侯龙。","风帘雾箔秋同被，玉室金堂夜不封。","说向九江李太白，结巢休羡古时松。"]},{"t":"题朱参政松石轩","f":"七言律诗","c":["长松落落风尘表，苍石庚庚太古心。","屹立乾坤无改色，扣如金玉有馀音。","人间儿女天机浅，海上神仙野趣深。","独有奇章知此适，子孙清赏到于今。"]},{"t":"题罗成之藏柯敬仲悬崖竹","f":"七言律诗","c":["丹邱画竹出新意，醉墨落纸秋淋漓。","青天低垂凤凰尾，碧海倒插珊瑚枝。","谁家俗士谩食肉，何处高人来赋诗。","丹房月夕起清思，莫遣风雷生葛陂。"]},{"t":"题马县尹寿椿堂","f":"七言律诗","c":["绵绵灵气与天游，日月盘旋定几周。","七十三翁同甲子，八千馀岁一春秋。","欲询齐物南华老，谁是平生马少游。","堂下芝兰森玉立，未容丹桂独风流。"]},{"t":"再游金山寺","f":"七言律诗","c":["放船重到金山寺，独对沧江照鬓丝。","过客谩惊天险处，老僧曾见海枯时。","通宵月色鱼龙喜，绝顶秋声鹳鹤悲。","琼树花开不归去，妙高台上要题诗。"]},{"t":"题石林茅屋","f":"七言律诗","c":["春林深深石如笋，我屋正在林之西。","结茅不放风雨入，种树乃与岗峦齐。","天寒白鹤向人语，日暮野鸟来上啼。","浣花老人不可作，何处客至同幽栖。"]},{"t":"题王维贤所藏盛子昭画双松系舟图","f":"七言律诗","c":["云门寺前风物幽，布袜青鞋吾昔游。","葫芦盛酒待明月，舴艋载琴当上流。","长松并立几千尺，狂客一别三十秋。","何当挂席过湖去，东里草堂姑少留。"]},{"t":"送郜彦清之浙西宪史时有高德晋同日应辟之江西所以诗中故及之","f":"七言律诗","c":["西浙西江同应辟，此时此会记清欢。","两贤共起诸侯幕，十载谁先御史冠。","野寺听蝉秋冉冉，津亭维马雨珊珊。","清时事业须公等，老我山中拭目看。"]},{"t":"题俞仲桓双林道人卷","f":"七言律诗","c":["双林道人如霜林，参天劲木寒萧森。","众芳到此万叶脱，元气授尔孤根深。","风前猛虎作人啸，月下清猿将子吟。","铁笛老仙在何许，吾欲载酒同幽寻。"]},{"t":"宿鹤沙张氏草堂","f":"七言律诗","c":["草堂借我作行窝，杖履频烦太史过。","满地白云清昼永，隔溪黄鸟绿阴多。","银瓶自泻中山酒，铁笛谁翻小海歌。","今日逢君须尽醉，西家亭馆奈愁何。"]},{"t":"次杨太史之韵题赠叶子澄草堂图诗","f":"七言律诗","c":["君家草堂林木幽，乃在吴会之东头。","花开从令鸟雀喜，水落正为鱼龙忧。","深林烂饮枸杞酒，如意醉击珊瑚钩。","丈夫嘉遁有如此，傍人比是神仙流。"]},{"t":"送陈希文北游","f":"七言律诗","c":["万里中原道路长，关河环绕五云乡。","心驰天上黄金阙，梦忆山中紫翠房。","人海鱼龙三月浪，御街车马五更霜。","丹墀奏罢中兴颂，燄燄声名动北方。"]},{"t":"题钱伯玉南园小隐","f":"七言律诗","c":["君是钱王几叶孙，浮云富贵不须论。","丈人屋上乌仍好，处士篱边菊尚存。","招隐辞章娱日月，表忠碑刻照乾坤。","明当载酒来相觅，烂醉君家老瓦盆。"]},{"t":"题杨仲德照磨自汴梁归话中原荆棘蔽野人烟断绝闻复山东感而赋此","f":"七言律诗","c":["故人归报朔方兵，已下山东七十城。","日月未教乌兔死，风云方使虎龙争。","入关谩尔窥周鼎，背水今谁立汉旌。","北望中原五千里，黄河之水几时清。"]},{"t":"重游虎邱寺","f":"七言律诗","c":["海涌峰头行径微，芒屦欲趁孤云飞。","风高木客作人语，月出天王骑虎归。","杰阁重楼递隐见，寒泉古木相因依。","荒邱王气岂消歇，干将莫耶千载稀。"]},{"t":"寄题松江之青龙瞿睿夫通波草阁诗","f":"七言律诗","c":["五月通波草阁寒，绿阴长日此凭栏。","山如碧凤参差出，江作青龙左右蟠。","榄子烧香云母火，樱桃行酒水晶盘。","老夫亦有鹅溪绢，也欲相从看写兰。"]},{"t":"寒舍为偷儿见顾窃去珠环首饰赋以自遣","f":"七言律诗","c":["太息偷儿也自顽，踰垣何意到山间。","潜踪深夜开重穴，竟造中堂启四关。","狱吏肯追全璧返，家人犹望去珠还。","愁来幸喜青毡在，觅纸题诗一解颜。"]},{"t":"题何德深溪南小隐","f":"七言律诗","c":["宰相官之不受招，碧梧林巷自逍遥。","溪头二月花先发，洞里千年雪未消。","朝士过门时载酒，仙人飞佩夜吹箫。","社图谁写耆英会，还肯中间著老樵。"]},{"t":"寒食日松江有怀广陵","f":"七言律诗","c":["老来也欲惜年华，春正浓时不在家。","江上苦遭寒食雨，梦中犹见广陵花。","书藏旧箧应无恙，酒忆新楼不用赊。","日暮荒城闻鬼泣，东风吹恨满天涯。"]},{"t":"送秀岩上人归日本","f":"七言律诗","c":["几年中国游方遍，看水看山念念非。","海眼枯时千劫坏，日头出处一僧归。","黄梅雨打袈裟湿，白蜃云随锡杖飞。","富士岩前留语在，庭松新长旧禅扉。"]},{"t":"题上海静安寺绿云洞天为宁为无寺之祖师虾子和尚","f":"七言律诗","c":["沪渎城西古道场，洞天深处绿云凉。","雨昏不辨琅玕色，日转都成翡翠光。","春水满溪虾子活，午阴当户鸟声长。","华阳老客家何在，拟伴高僧坐石床。"]},{"t":"别茅府判","f":"七言律诗","c":["封印归来寡送迎，画桥门巷水同清。","二分明月杯中泻，九朵春云笔下生。","宾客班荆谈雅道，儿童骑竹颂廉声。","奚须老拙扬人善，公府争传好姓名。"]},{"t":"三月十日移居","f":"七言律诗","c":["山人垂老厌奔波，客里移居可奈何。","居竹轩中无长物，采莲泾上有行窝。","几茎白发梳来短，千古清尊饮尚多。","最喜东邻王处士，闲来无事肯相过。"]},{"t":"送毛自得北游","f":"七言律诗","c":["平原门下客三千，毛遂当时独妙年。","脱颖机锋吾已得，治安筹策子何先。","江淮故道苍烟外，楚汉孤城落照边。","今日送君何限意，秪将忠孝足家传。"]},{"t":"次饶介之游东皋佳作 其一","f":"七言律诗","c":["半雨半晴春更佳，也知郭外少纷华。","蛮王埠头多载酒，李家园中来看花。","曲阑芳槛递隐见，苍松老竹相交加。","安得长绳系乌足，不放西崦红日斜。"]},{"t":"次饶介之游东皋佳作 其二","f":"七言律诗","c":["纵饮狂歌晚未归，松阴香雾转霏微。","醉中漫喜朱颜在，头上争禁白发稀。","无数野花迎客喜，一双沙鸟傍船飞。","浣花溪上真堪笑，每日朝回只典衣。"]},{"t":"次饶介之游东皋佳作 其三","f":"七言律诗","c":["草草杯盘也自佳，名园今日有光华。","东风淡起云漠漠，胡蝶飞上芜菁花。","百年酒伴无多在，一夜春愁十倍加。","明朝应被傍人笑，醉里题诗字半斜。"]},{"t":"次饶介之游东皋佳作 其四","f":"七言律诗","c":["不用人扶醉里归，水边杨柳晚风微。","一年春事又将半，三月捷音何太稀。","莫倚书囊谈未了，却凭藜杖步如飞。","入城彷佛严更动，冉冉花香尚满衣。"]},{"t":"同张仲举宿寒桥","f":"七言律诗","c":["柔橹声乾破寂寥，青山矶下宿寒桥。","乾坤万事双蓬鬓，风雨孤舟半夜潮。","丹凤不来秋又老，玉人何处水空遥。","几时更醉秦淮酒，细听渔樵话六朝。"]},{"t":"李子英心远亭","f":"七言律诗","c":["门外黄尘扫不开，何由吹得到灵台。","閒看倦鸟投林去，静爱孤云出岫来。","彭泽高人多逸兴，峨眉仙客有天才。","祗今谁到悠然处，同采秋香共一杯。"]},{"t":"寄王仲沔御史左迁之安庆府判诗","f":"七言律诗","c":["青骢马鸣催趣装，日出未出江茫茫。","但愿四海有武备，不可一朝无宪纲。","搀抢经天堕作石，沆瀣着地凝为霜。","先生忧国鬓未白，至今台柏留辉光。"]},{"t":"王澹园明道堂","f":"七言律诗","c":["重阑飞构入清溟，虎豹森罗户不扃。","紫气拥关周问礼，玉光浮座汉传经。","日斜海雾侵香案，夜静天风语铎铃。","几度澹渊来说法，泉中应有老龙听。"]},{"t":"送袁季文之帅幕","f":"七言律诗","c":["少年书剑学从军，幕府于今气不群。","白发元戎多好武，青衫从事最能文。","帐前草檄花如雨，江上维舟水似云。","把酒高歌成远别，不知何处又逢君。"]},{"t":"送张士行士明会试","f":"七言律诗","c":["山东秋榜得豪英，谁似君家好弟兄。","四海宾兴得两举，七千乡贯占三名。","大苏衣钵都源委，小宋文章更老成。","明日鸰原同送喜，早将春信到江城。"]},{"t":"南城暮春","f":"七言律诗","c":["南城雨尽午风和，二客相从步屧过。","流水陂塘春事减，落花门巷晚愁多。","银瓶自泻沙头酒，宝瑟谁调陌上歌。","莫写江南断肠句，贺郎憔悴发空皤。"]},{"t":"寄湖州乌雅太守时有福建参政之除","f":"七言律诗","c":["万里中原路未开，谁倾银汉洗氛埃。","诸公多向江南老，远使频从海上来。","九月溪寒鸥梦熟，三山秋暝鹤书回。","莫挥白发新亭泪，且醉乌程下若杯。"]},{"t":"次韵答冯仁伯","f":"七言律诗","c":["闭门风雨过重九，却忆同登江上台。","独客诗成扶病起，故人书到拆封开。","自怜风物随南土，谁有文章落上台。","黄菊紫萸浑未见，兴来聊复举吾杯。"]},{"t":"甫里先生故宅是时马县尹葺其庙","f":"七言律诗","c":["太湖三万六千顷，一代高贤独此翁。","故宅有僧茶灶在，荒池无主鸭阑空。","松陵唱和知谁再，茅屋襟期与我同。","最爱长洲马明府，艰危犹自挹高风。"]},{"t":"周平叔夜宿崇明寺海云楼偕罗成之隐君文长老及卢隐君以沙头双瓶为韵各赋诗四首次韵卷后 其一","f":"七言律诗","c":["沧洲三月住星槎，闻访青原隐者家。","四老咏歌能玩世，百年聚散若抟沙。","饥来且食书中粟，老去空悲镜里花。","明日分携各努力，暮云回首隔天涯。"]},{"t":"周平叔夜宿崇明寺海云楼偕罗成之隐君文长老及卢隐君以沙头双瓶为韵各赋诗四首次韵卷后 其二","f":"七言律诗","c":["老去无因接胜游，题诗烦寄海云楼。","天空直与海无底，云起正当楼上头。","黑水几程通直谷，青山一发是瀛洲。","高明境界无尘到，抚卷令人咏未休。"]},{"t":"周平叔夜宿崇明寺海云楼偕罗成之隐君文长老及卢隐君以沙头双瓶为韵各赋诗四首次韵卷后 其三","f":"七言律诗","c":["天台老衲两眉庞，自起高楼枕石杠。","煮茗别开留客处，论文多近坐禅窗。","冥鸿散去犹相逐，独鹤飞来不作双。","明发仙舟上霄汉，定传诗话满沧江。"]},{"t":"周平叔夜宿崇明寺海云楼偕罗成之隐君文长老及卢隐君以沙头双瓶为韵各赋诗四首次韵卷后 其四","f":"七言律诗","c":["天水空明接杳冥，老禅三昧解通灵。","欲将东海为平地，尽捲西江入净瓶。","宿霭微分沙鸟白，晚风犹带毒龙腥。","他时月夜来相觅，笑指狼峰五朵青。"]},{"t":"邱克庄敞云楼","f":"七言律诗","c":["君家楼外云如海，五色轮囷扫不开。","每就月明檐下宿，更随秋色座中来。","琼台夜鹤迷踪迹，玉女春衣费剪裁。","看汝乘将朝帝所，举头西北是蓬莱。"]},{"t":"题玉岩上人溪山野趣图","f":"七言律诗","c":["流水淙淙石齿齿，满庭云气欲模糊。","白鸥溪上秋多少，黄叶山中路有无。","十月雨深渔屋破，三江风急野航孤。","年来难觅幽居处，空向晴窗看画图。"]},{"t":"寄越上能仁寺用章俊禅师","f":"七言律诗","c":["几年卓锡住苕溪，一日寻山入会稽。","蒲室塔曾藏舍利，道林堂已种菩提。","空中云气开楼阁，门外湍声杂鼓鼙。","草木变迁吾老矣，隔江南望转凄迷。"]},{"t":"和周伯温参政九日南园宴集诗二首 其一","f":"七言律诗","c":["步履巉岩若跨鳌，望中诗兴与秋高。","西山拄笏东山屐，右手持杯左手螯。","返照入湖明塔影，断云将雨过林皋。","松间饮散归来晚，金粉霏霏湿锦袍。"]},{"t":"和周伯温参政九日南园宴集诗二首 其二","f":"七言律诗","c":["范相南园五百秋，重来访古转多愁。","啼乌树老台空在，饮马池荒水不流。","芹泮好从多士乐，桂丛谁赋小山幽。","诸公高会诗如锦，授简安能接胜游。"]},{"t":"嘉兴缪同知号菊陂因赋","f":"七言律诗","c":["杰哉霜下转精神，一色中黄不染尘。","老圃看花迎宰相，秋潭分水候仙人。","千年东里归何早，九日南陂赏□□。","在昔神农书上药，至今医国慰斯民。"]},{"t":"马瞿睿夫题张伯雨外史评黄子久画仙山楼观图","f":"七言律诗","c":["陵谷东南几变迁，琼台仍在白云边。","阎浮世上今何日，句曲山前第八天。","说法久要狂外史，挥毫曾识大痴仙。","人间俯仰三千岁，抚卷题诗一惘然。"]},{"t":"贺耕叟晚香亭","f":"七言律诗","c":["幽香分得东篱本，每候开时九月前。","晚岁谁从陶靖节，高风独数傅延年。","清秋泛酒宾筵盛，白发簪花客帽偏。","若个芬芳同老境，魏公佳句至今传。"]},{"t":"二月十四日风雨孤坐秀州城西僧舍赋此","f":"七言律诗","c":["秀州城西春事微，二月苦雨行人稀。","江湖渺然不可渡，风雨如此将安归。","老来口腹胡为累，乱后人民今见非。","兼旬不得武陵信，倚杖南望孤鸿飞。"]},{"t":"送马令尹任满","f":"七言律诗","c":["长洲赤子穷无告，正赖郎官为抚摩。","兵后人家犹耒耜，日长官社有弦歌。","越来溪上波声小，鲁望祠前月色多。","自古长才须大用，荐书元不待常何。"]},{"t":"题嘉兴水西寺爽溪楼寄新仲铭长老","f":"七言律诗","c":["新公邀作爽溪游，为说前朝有此楼。","云气远开天北极，风光仍在水西头。","虚檐古瓦缘苍鼠，曲涧轻波漾白瓯。","宸翰仅留飞白在，烟尘漠漠使人愁。"]},{"t":"贺长洲县令尹马公除枢密院都事","f":"七言律诗","c":["报政期年上考书，君才端合应时须。","三公掾属多为相，两府郎官半是儒。","夜帐论兵银烛抚，春庭称寿綵衣趋。","苍生久堕巅崖苦，定有嘉言赞庙谟。"]},{"t":"次张仲举侍读韵","f":"七言律诗","c":["词源浩浩倒岷江，直笔如公世少双。","目下十行千字过，身长九尺两眉庞。","世间忠烈应知感，地下奸谀岂竖降。","老客中吴最萧索，白头犹尔读书窗。"]},{"t":"东饶介之","f":"七言律诗","c":["鲁连不为商贾事，贺监自是神仙人。","解纷排难乃豪杰，嗜酒狂歌非隐沦。","燕雀一生谋水食，凤凰千仞出风尘。","太湖之水东作海，海上桃花树树春。"]},{"t":"寄张内翰","f":"七言律诗","c":["中原不见旧山河，使节仍烦涉海波。","天末草烟春信早，江南风雨客愁多。","谢公拟献中兴颂，壮士宁忘敕勒歌。","万里相忘成永决，白头萧索柰公何。"]},{"t":"题王仲德思诚斋 其一","f":"七言律诗","c":["六凿相攘总失真，一诚无妄见斯人。","指挥直拟回天地，祭祀还能给鬼神。","别室蓍龟先兆汝，前楹鸟雀自相驯。","明年执玉朝廷上，会见尊严动缙绅。"]},{"t":"题王仲德思诚斋 其二","f":"七言律诗","c":["爱汝端居入静思，察机尤在未萌时。","天人孚感原无间，物我交攻每日持。","行远升高应得已，斋心浴已固知之。","屈伸洞见阴阳理，荣瘁休嫌风露枝。"]},{"t":"赋得落星湖送瞿睿夫任满之诗","f":"七言律诗","c":["南湖北湖春水多，陨石下筑神龙窝。","渚花汀草各无赖，云影天光相荡摩。","天星劝汝一杯酒，海月听我千年歌。","斗牛之槎若可待，送子八月乘银河。"]},{"t":"钱塘谢太守有书见邀作此诗以谢之","f":"七言律诗","c":["一缄远寄楚狂生，上有钱塘太守名。","堆案几时疑是梦，焚香三读见高情。","五湖风月曾宾主，四海交游总弟兄。","少待西风渐凉后，六桥荒藓尚堪行。"]},{"t":"饶介之有诗见贻次韵奉荅 其一","f":"七言律诗","c":["一夜南风约晓晴，看山如在越中行。","丹藏别室生虹气，啸入空岩作虎声。","倒涧枯松留古怪，悬崖飞瀑漱寒清。","神仙若个能千岁，吾欲崆峒问广成。"]},{"t":"饶介之有诗见贻次韵奉荅 其二","f":"七言律诗","c":["数日南风阴复晴，饭馀閒绕绿阴行。","竹间病鹤缡褷影，池上惊鱼拨刺声。","老子鬓毛如此白，道人心迹本来清。","能诗谁是周公子，学得阴何五字成。"]},{"t":"贺李左丞再入中书","f":"七言律诗","c":["上公开府驭群英，妙算神机属老成。","裴度向来归绿野，谢安重起为苍生。","朝廷约法三章旧，天地功成百谷盈。","不有武功除暴虐，岂无文教答升平。"]},{"t":"万壑松涛为郜彦清赋","f":"七言律诗","c":["草堂夜夜听松涛，谁挽沧溟压树梢。","雷谷震惊龙换骨，风林摇荡鹤倾巢。","玉山月白箫声杂，银汉天清剑气交。","我与周弘同洗耳，乘槎便欲渡三茅。"]},{"t":"寄周平叔就求苍耳子","f":"七言律诗","c":["周侯久不通书问，夜夜沧江入梦频。","五月采来苍耳子，几时分送白头人。","沙头酒熟田毛足，港上船来海错新。","南北相望千百里，老来幽独倍伤神。"]},{"t":"再题郜彦清万壑松涛","f":"七言律诗","c":["秋入空山万窍鸣，山前山后乱潮生。","不知天籁非人籁，却认风声似海声。","直干也随羊角旋，高枝唯恐鹤巢倾。","毕宏韦偃还听否，惨淡经营画得成。"]},{"t":"苏台晚望","f":"七言律诗","c":["野色苍茫落照中，荒台扶杖倚秋风。","延陵百里吴封旧，震泽三江禹迹空。","浊酒更须浇磊磈，黄金不解铸英雄。","侧身北望中原近，几处神州正朔同。"]},{"t":"送谢太守平江省亲回武林就送鹅酒之贶","f":"七言律诗","c":["五马既秣车载脂，上堂欲别还迟迟。","拜家已得阿母喜，还郡即慰邦人思。","几年东阁旧倾盖，今日西湖谁赋诗。","野翁惭无一字补，辄敢笼鹅临墨池。"]},{"t":"送张师廉归富春","f":"七言律诗","c":["读书不逢万乘尊，献策岂傍诸侯门。","放歌苏台晚山碧，濯足太湖秋水浑。","千金未易买骏骨，一饭何足哀王孙。","风尘拂衣且归去，高卧桐江云水村。"]},{"t":"寄题海上积善庵水竹轩","f":"七言律诗","c":["水阁云廊深复深，开轩绿雾常阴阴。","凉宵濯足月在港，清昼读书风满林。","食笋也胜鱼肉味，截筒谁作凤凰吟。","清凉更在声尘外，夜夜海潮生妙音。"]},{"t":"题何永孚瓶斋","f":"七言律诗","c":["井湄须问扬雄酒，松下空藏智永书。","一日挈之来市肆，百年将汝置斋居。","龙泉旧物魁名在，鹤发仙翁手泽馀。","我亦有瓶谁抚玩，新诗题罢转愁予。"]},{"t":"七月久阴十日甲子复大雨","f":"曲","c":["七月十日甲子雨，彻夜檐溜无休时。","野老惊呼后土湿，秋田仰望皇天慈。","饥乌觅食亦散漫，病鹤顾影空缡?。","青泥没屐不可出，虾菜何以供晨炊。"]},{"t":"题黄冈贾彦德碧梧轩","f":"七言律诗","c":["贾谊井西梧十寻，百年秀发根株深。","银床分润长新叶，翠竹交枝成好音。","季春花香自零落，高秋雨气相萧森。","何当临轩坐白石，为子再歌孤凤吟。"]},{"t":"寄题松江徐君瑞柳堂","f":"七言律诗","c":["稚柳一岁高于母，濯濯风流健似人。","九烈效灵连送客，三眠扶起并留春。","状如车盖生来异，色比宫袍染更新。","入对长杨应未晚，马前飞絮扑香尘。"]},{"t":"送韩仲让都司梁溪督兵防秋","f":"七言律诗","c":["今人勋业古人心，立马梁溪恨满襟。","兵谶谩传山有锡，军装端信橐无金。","风高古垒黄花晚，霜落平原白草深。","南省相君方倚重，边廷穷虏敢相侵。"]},{"t":"贺毅刚中长老住承天禅寺诗二首 其一","f":"七言律诗","c":["十刹亲题请疏开，法筵击鼓动春雷。","自离南楚传灯后，重为东吴倡道来。","两柱承天行日月，六鳌从地涌楼台。","灵山诸佛生欢喜，散作祥风遍九垓。"]},{"t":"贺毅刚中长老住承天禅寺诗二首 其二","f":"七言律诗","c":["海上东来转法轮，祖衣传久色逾新。","携将天目山中雨，洒向蛾眉石上尘。","行道要从无佛处，开堂须著有缘人。","等閒拈出菩提子，百草千花不当春。"]},{"t":"九月一日寄谢太守","f":"七言律诗","c":["出入侯门五见春，每承分粟济清贫。","托交独喜君知我，临老犹将子累人。","公论几时令捧檄，私恩有日效扶轮。","鱼书一札珍藏在，白发西湖愿卜邻。"]},{"t":"谢王左丞鹅酒之惠","f":"七言律诗","c":["深巷曾经显者过，春风披拂到松萝。","右军墨沼笼鹅在，左相官瓶送酒多。","乡井未忘生处乐，江湖犹赋醉时歌。","阶墀久不投名刺，奈此衰翁老病何。"]},{"t":"题觉报寺茂元长老白云窝","f":"七言律诗","c":["白云窝里烂如银，不住虚空着幻身。","趺坐也教龙入定，巢居还许鹤为邻。","自缘色界闲来往，谁与天香作主宾。","若问吾家安乐法，老夫曾学避秦人。"]},{"t":"送松江朱焕章之乌程令尹","f":"七言律诗","c":["新除令尹乌程去，霜落湖田十月初。","貂帽锦衣怀印绶，青帘白舫载图书。","到官先谒将军府，省俗仍陪太守车。","东望吴淞三百里，莫因莼鲙赋归欤。"]},{"t":"题元上人怡云轩","f":"七言律诗","c":["白云本是山中物，暂与山僧作主宾。","尔解自舒还自捲，我能无喜亦无嗔。","半间莫惜分馀地，一笼犹思赠远人。","句曲有家空在望，卜居何日许为邻。"]},{"t":"王唯贤东里草堂","f":"七言律诗","c":["平安一桥吾旧游，君屋乃在桥东头。","晚山得月更宜酒，春水到门还放舟。","太守诗成写素壁，老夫兴发思沧洲。","淮南丛桂不得往，抚卷因之生远愁。"]},{"t":"送黄观澜尚书吴伯尚廉使之江西征讨 其一","f":"七言律诗","c":["白发儒臣著武冠，公卿相送出朝端。","恭承斧钺行天讨，喜见旌旗拥夏官。","直北声名从此振，平南筹策有人看。","虎皮会见包戈甲，十郡苍生奠枕安。"]},{"t":"送黄观澜尚书吴伯尚廉使之江西征讨 其二","f":"七言律诗","c":["江西寇盗本王民，正赖诸公为解纷。","使者精忠悬白日，尚书高义抗浮云。","喜传天上旌旗出，肯使山中玉石焚。","千古鲁连高世士，尚将谈笑却秦军。"]},{"t":"送罗成之移居崇明其子季通亦之本州校官","f":"七言律诗","c":["先生八月乘烟雾，妻子同随海上槎。","太守宾筵先肃客，广文官舍即为家。","波涛浩荡藏阴火，岛屿微茫接太霞。","闻说三洲多药草，可能无意到丹砂。"]},{"t":"送罗季通之崇明学政","f":"七言律诗","c":["海上孤舟作冷官，也知清选重儒冠。","秋潮好掣珊瑚网，晓日休歌苜蓿盘。","士子几家能食禄，汝翁早岁已遗安。","老人亦有乘桴意，僦屋西沙度岁寒。"]},{"t":"八月三日书所见","f":"七言律诗","c":["青军黄军日自斗，西城南城门不开。","诸侯相对面似土，今我不乐心如灰。","饥乌在树噤无语，苍蝇满案从何来。","年衰但愿饱粝食，意到聊且持吾杯。"]},{"t":"秋日登甘露寺晚眺","f":"七言律诗","c":["醉里摩挲望眼开，江天寥落暗风埃。","犹闻西府兵麾满，不见中原驿马来。","今日贾生须痛哭，当时祖逖是英才。","翩然一笑下山去，试看高僧话劫灰。"]},{"t":"送孔士瞻宪史考满归曲阜","f":"七言律诗","c":["素王之后多贤者，清稼今为几代孙。","能以纪纲持宪法，每将节义答君恩。","江淮一道风霜肃，汝颍三秋雾雨昏。","不有俊良当世用，可无章疏达天阍。"]},{"t":"送张明善归武昌随又移家眷入蜀","f":"七言律诗","c":["对酒悲歌泪满衣，楚天摇落又斜晖。","风尘万里与君别，江海一舟何处归。","老去且留吾舌在，愁来长惜壮心违。","临岐不尽平生意，沙苑无云鹤自飞。"]},{"t":"南安周知事瑞雀","f":"七言律诗","c":["岁岁双栖傍主人，昔年谁与号嘉宾。","应图夜半衔环报，不比阶前得食驯。","公干题诗犹未远，不疑作颂秪如新。","东风更得周郎便，看尔翩翩上苑春。"]},{"t":"送广东帅郎郑彦昭贡香药入京诗一首","f":"七言律诗","c":["万里番禺入贡来，过淮一日到蓬莱。","海中药草无人识，天上桃花有处栽。","圣代宾兴方重士，星郎年少况多才。","也知白璧虞卿礼，犹在黄金郭隗台。"]},{"t":"谢冯仁伯送米与舒雁","f":"七言律诗","c":["短发晨梳雪几茎，老来那复爱虚名。","只凭药饵扶衰朽，更藉诗篇写性情。","天地此心唯报主，江淮多事尚闻兵。","香粳分得谁相送，舒雁笼来未忍烹。"]},{"t":"送马士瞻帅掾高擢","f":"七言律诗","c":["风尘如此送君行，念尔才华独老成。","军旅未闻忘俎豆，掾曹多见到公卿。","沧江日射旌旗影，紫阁风悲鼓角声。","玉麈谈玄何事业，云台图像是功名。"]},{"t":"寄静逸处士顾仲庸","f":"七言律诗","c":["环堵萧然一室宽，只除诗酒寄清欢。","瓶中有粟分寒士，袖里无书上热官。","扬子暮年空识字，庞公早岁已遗安。","先生独卧风尘表，吾欲相从接羽翰。"]},{"t":"题周子端恻隐斋","f":"七言律诗","c":["此心随感与天同，念尔斯人水火中。","拯溺未能空下涕，救焚何以自成功。","百年底事多残忍，四海于今喜扩充。","将见运之于掌上，世间无物不春风。"]},{"t":"吾欲卜居海上未有定止先作诗寄紫步刘子彬","f":"七言律诗","c":["满目风尘秪自怜，轻装已办有行缠。","也知避乱依城郭，更欲移家傍渚田。","紫步于今无士马，沧溟何处有神仙。","桃源只在人间世，还许渔郎放钓船。"]},{"t":"送遆思诚出盱眙教谕","f":"七言律诗","c":["年年送人作校官，也知当代重儒冠。","固因学舍人才盛，自觉戎藩礼数宽。","一县士风今日见，百年师道后来看。","淮山堂上清于水，莫遣惊尘到杏坛。"]},{"t":"和张仲举博士见寄至日诗","f":"七言律诗","c":["衡门风雪人稀到，一个幽轩竹四围。","半子送年将旧酒，诸孙迎岁索新衣。","惊鸿此日犹南去，老鹤何年共北飞。","却忆太常张博士，天香携袖早朝归。"]},{"t":"题渔乐手卷","f":"七言律诗","c":["江湖如此两閒人，除是玄真与季真。","长笛自吹皆古调，短篷相并即比邻。","科头不异今渔者，托迹空闻古逸民。","亦有渌阳湖上客，买舟来约理丝纶。"]},{"t":"十一月十四日有感寄江州太守李子威 其一","f":"七言律诗","c":["清朝如此盛公卿，何以摅忠答圣明。","数月未收蕲水贼，一时谁散武昌兵。","朱门旧邸空文藻，黑夜归舟有哭声。","独使状元贤太守，至今犹捍九江城。"]},{"t":"十一月十四日有感寄江州太守李子威 其二","f":"七言律诗","c":["边报传来实失惊，妖氛独不犯湓城。","义兵一日同生死，信史千年托姓名。","别戍几人回士马，沧江通夜走公卿。","九州尽得如公者，始信文儒有老成。"]},{"t":"赋吴陵凤凰池送陈子成","f":"七言律诗","c":["蓬莱阁前春水生，丹邱之凤双飞鸣。","沧波照见云锦色，碧落散作箫韶声。","岂无仙人下刷羽，亦有隐者来濯缨。","池上于今望吾子，一曲阳春歌太平。"]},{"t":"和张仲举五月荐樱桃之作","f":"七言律诗","c":["四月上林蒲笋出，玉堂风致一时新。","也知天上樱桃宴，不致山中草莽臣。","皂帽醉归当此日，金盘分赐共何人。","吾家一树红堪摘，取荐春醪莫笑贫。"]},{"t":"送傅德润陪将作同知武昌买马回京","f":"七言律诗","c":["维扬馆里送轺车，却算分携八载馀。","天使出求沙苑马，星郎厌食武昌鱼。","数鞭已报充华厩，上冢毋忘过旧庐。","老我平生无骏骨，可从郭隗借吹嘘。"]},{"t":"送霍仲皋还京","f":"七言律诗","c":["驿程万里入皇都，还过梁城取别途。","天下军需何日了，淮南民瘼几时苏。","求田问舍非良策，忧国忘家是壮图。","黄阁相君应有问，愿闻一语赞嘉谟。"]},{"t":"送盛克明辟掾浙省移家吴兴","f":"七言律诗","c":["十年三送沧江别，此日分携又不同。","辟掾远趋青锁闼，移家喜近水晶宫。","勿论后会知何地，且念离群独老翁。","幕府郎君应问讯，为言憔悴坐诗穷。"]},{"t":"和周子通助教同张元祯倡和诗卷子","f":"七言律诗","c":["懒性何堪接贵游，松江之下每科头。","不能取友山中社，更欲移家海上州。","老去生涯清似水，兴来诗思淡于秋。","玉堂杰作难为和，白首狂吟秪自愁。"]},{"t":"奉寄李子洁宪副时湖北残破却于太平开司","f":"七言律诗","c":["武昌遗老望旌旗，正是诸君报国时。","令弟九江全死节，明公南海有生祠。","台中妙选邱山重，湖北先声草木知。","一道宪纲还旧睹，真儒端可佩安危。"]},{"t":"题崔原亭竹深处予家有竹数竿人号曰居竹轩原亭城西别墅有竹亦数竿则又号之曰竹深处予与崔君通家来往所好相同故及之","f":"七言律诗","c":["居竹轩中也自宽，不愁无地著琅玕。","文公胸次空千亩，李洞门前只一竿。","天与老夫医恶俗，日凭童子报平安。","崔家别墅尤高致，迟子归来守岁寒。"]},{"t":"经山法城禅师高弟善上人以楚章为号因题卷后","f":"七言律诗","c":["从向经山礼法城，善端开后愈分明。","千年楚国非无宝，一个吴僧得此名。","江月自随行道影，风林犹听读书声。","旧家白雪亲曾和，处处丛林得散行。"]},{"t":"题丹阳邹隐君自得斋","f":"七言律诗","c":["天宇清明淑气微，昔年曾约试春衣。","傍花随柳无人识，弄月吟风只自归。","达士一生空好饮，老夫六十始知非。","陶然不得从君乐，注目沧江白鸟飞。"]},{"t":"题阳学训曹元秉归溧水","f":"七言律诗","c":["先生武惠之子孙，粹然言貌如春温。","清门为庶忽老大，白首穷经犹讨论。","诸生分题候堂试，二膳击鼓供盘餐。","今晨拂衣不肯住，兴在江南山水村。"]},{"t":"题苏文仲中宣使宝善斋","f":"七言律诗","c":["星郎自是鲁璠玙，宝善称之信不诬。","岂与黄金同日语，合登清庙应时须。","渑池漫诧连城璧，沧海空传照乘珠。","何似人中无价者，君家先世有三苏。"]},{"t":"送娄所性归溧水","f":"七言律诗","c":["大学小学列六斋，先生讲席多英才。","公堂昕鼓会食罢，门榜月录分题来。","清时如此教养备，老夫一见心神开。","束书胡为赋归去，石田未必荒苍苔。"]},{"t":"次陈养吾见寄韵","f":"七言律诗","c":["我本沧江樵牧人，却怜垂老见风尘。","边城笳鼓伤心近，野寨旌旂入望新。","四海正歌垂拱日，百年犹忆至元春。","艰难未改心如铁，潦倒空悲发似银。"]},{"t":"送尹敬思令尹归青州并序 其一","f":"七言律诗","c":["玉雪丰神未七旬，江淮谁识旧儒臣。","眼空四海归何早，胸著千年汲愈新。","从学王门唯此老，发挥朱子更何人。","青州门外京华近，吾欲相从一问津。"]},{"t":"送尹敬思令尹归青州并序 其二","f":"七言律诗","c":["宪签被旨方修律，令尹归田独著书。","一代仪刑留制作，十章条目补遗馀。","青州高起耆英社，白发同乘泽下车。","不得清风接芳躅，可凭短札问何如。"]},{"t":"七月十日浙省有警怀罗善先掾史后闻使闽未回","f":"七言律诗","c":["淮楚风尘可奈何，南州又复动干戈。","三山城郭故人远，八月江湖夜雨多。","白发满头同老境，沧洲何处可行窝。","裁书欲问平安否，海阔天高雁未过。"]},{"t":"蒋文甫以其祀亲之室扁曰思斋时余方哭母故及之","f":"七言律诗","c":["老去思亲十二时，灯前犹诵蓼莪诗。","烝尝彷佛归来也，颜色分明梦见之。","问寝不忘晨起早，倚门谁念暮归迟。","多君苦行多于我，忍听长原楚些词。"]},{"t":"送娄所性回金陵别业","f":"七言律诗","c":["楚甸惊尘满客衣，古之贤达在知几。","山中桂树我将老，江上草堂君独归。","刁斗连城严肃肃，旌旗垂野净辉辉。","金陵酒熟还相忆，莫遣诗筒信使稀。"]},{"t":"简江西宋子与令尹杨翼之李斯立二先生","f":"七言律诗","c":["八月凉风催早寒，家山空忆路漫漫。","沧江无处问书信，白日何人生羽翰。","晓雾瘴天迷故国，夜潮流月到长干。","诸君莫责王夷甫，我辈深惭管幼安。"]},{"t":"题海陵张孝子传","f":"七言律诗","c":["汝翁早岁值风尘，与母分离三十春。","远道求之疑隔世，高堂喜极转伤神。","干戈满地方多事，骨肉全家有几人。","甚欲题诗歌孝子，老怀兴感恐沾巾。"]},{"t":"哭江州太守李子威","f":"七言律诗","c":["将帅怆惶忽弃城，孤忠何以独支撑。","尚闻传檄诛狂寇，犹自开仓举义兵。","千古报君心未死，九江图像面如生。","至今月黑匡庐下，彷佛悲风有战声。"]},{"t":"哭湖广省郎中刘遵道","f":"七言律诗","c":["百年正气此销沈，空使诸公泪满襟。","厚地无人收白骨，皇天有眼识丹心。","亲王兵卫终难倚，太尉楼船不可寻。","一自岳阳开省后，更无消息到于今。"]},{"t":"哭御史张彦威","f":"七言律诗","c":["平生恨不识张桓，烈烈轰轰御史官。","生有高风惊海内，死无遗憾负台端。","盘根错节于今见，孝子忠臣后代看。","一片汝阳城下土，何人高义葬衣冠。"]},{"t":"十月一日闻徐州复","f":"七言律诗","c":["黄河不解洗彭城，空使群凶起斗争。","一载始通南国贡，三山犹驻朔方兵。","寄奴故里人何在，亚父荒陵土欲平。","却忆朱陈好村落，几时烟雨看春耕。"]},{"t":"王彦芳得月楼","f":"七言律诗","c":["栋宇依稀接广寒，通宵月色好相看。","人閒尘土无来处，天上神仙正倚栏。","子晋吹箫秋引凤，常娥飞佩夜乘鸾。","兴来拟借清光便，碧海三山振羽翰。"]},{"t":"胡云夫槎山手卷代人作","f":"七言律诗","c":["故山西望白云飞，几向江楼倚夕晖。","藜杖只随浮世在，草堂终待主人归。","长开箧笥看华翰，不遣风尘上彩衣。","今夕羽书连报捷，灯花先喜到亲闱。"]},{"t":"送秘书太卿高志道总戎淮西","f":"七言律诗","c":["秘阁儒臣读武经，亲承斋斧下清溟。","鱼龙出海瞻卿月，牛斗回天避将星。","扫荡妖氛清社稷，指挥能事速风霆。","玉堂岂少昌黎笔，重刻平淮第一铭。"]},{"t":"王彦芳逢春坞","f":"七言律诗","c":["雪窗深锁不曾开，却似阳春有脚来。","琼树每从天上见，杏花多近日边栽。","任教南国芙蓉怨，莫遣东家蛱蝶回。","小圃无多闲草木，也分生意发枯荄。"]},{"t":"莲花鲊为顾从母夫人寿","f":"七言律诗","c":["采花曾入水云乡，谁有仙人服食方。","分饷恰如芦菔味，开包犹带芰荷香。","瑶池阿母亲曾造，画桨吴姬恐未尝。","更折碧筒来送酒，一时称寿献高堂。"]},{"t":"和娄所性见寄韵","f":"七言律诗","c":["想见沧洲白鸟双，寒潮依旧落空江。","移家有日同春酒，剪烛何人共夜窗。","欲寄短书心未展，每传佳句意先降。","吾家岁晚风流甚，雪后冰齑尚满缸。"]},{"t":"王元刚竹所","f":"七言律诗","c":["手种新梢已拂云，满林苍翠乱纷纷。","龙蛇影动当窗见，鸾鹤声来隔座闻。","东里先生常直造，西邻隐者欲平分。","沧江岁晚多霜雪，与尔知心独此君。"]},{"t":"和顾仲庸韵兼谢送米","f":"七言律诗","c":["醉里高歌若有神，山林无处著閒身。","饥来欲问餐松者，老去犹为乞米人。","织女机空星化石，麻姑酒尽海生尘。","洒清溪上梅花发，谁共先生醉好春。"]},{"t":"和黄观澜军前见寄韵兼呈高志道秘卿","f":"七言律诗","c":["干戈久动阻淮滨，喜得边庭捷报真。","东海鱼虾初入馔，中原桑枣半为薪。","秘卿船未移涡口，左辖军先入寿春。","多少手无兵刃者，可怜犹是贼中人。"]},{"t":"十二月十九日北门书所见","f":"七言律诗","c":["岁云暮矣北风凉，独立高楼望大荒。","雾气似尘黄作色，日轮如血赤无光。","经纶尚有诸公在，韬略原非我辈长。","凭仗天威驱号令，由来和气致休祥。"]},{"t":"寄四明梦堂噩禅师兼简用堂上人","f":"七言律诗","c":["五山十刹郁嵯峨，独爱溪堂隐薜萝。","淮海故人今有几，江湖尊宿近无多。","不闻毛女求诗去，每见倭僧问法过。","说向梗公重相忆，碧云日暮奈愁何。"]},{"t":"寄噩禅师四十年前在天宁方丈曾有求赋毛女诗","f":"七言律诗","c":["短杖轻袍归去来，水云多处少尘埃。","一春海鸟依檐宿，五月溪莲绕舍开。","云外送僧归日本，月中携客过天台。","衰翁不得瞻圆相，犹望新诗托雁回。"]},{"t":"送马易之回四明","f":"七言律诗","c":["雨水经旬雪复作，巷陌春泥断往来。","东海祗留诗卷在，南湖谁送酒船回。","自惭白发殷勤别，可惜琼花次第开。","我忆慈溪旧游地，不知淮泗有风埃。"]},{"t":"送季平仲教谕回通州","f":"七言律诗","c":["县庠官满将归日，圣代宾兴大比年。","备榜已闻居第一，前程谁谓隔三千。","兹晨剑影黄尘外，后夜书声碧海边。","少待秋风丛桂发，鹿鸣看尔赴初筵。"]},{"t":"送曹德辅州判率淮农三百人赴畿内垦田之行","f":"七言律诗","c":["茱萸湾上发官航，农事相催入帝乡。","玉雪手标多似舅，风云意气已为郎。","诸公妙算回天地，百谷神功叶雨旸。","来岁随班见明主，定颁鸾诰锡高堂。"]},{"t":"送刘禹玄州判率农夫多人诣畿垦田","f":"七言律诗","c":["京畿华壤尽提封，开辟抡材献九重。","使者传宣来万里，郎官分职领三农。","江淮田赋方全免，邦国军需足上供。","今日送君歌此曲，庙堂无复虑年凶。"]},{"t":"送清淮叟上人游五台","f":"七言律诗","c":["雁门西畔是灵山，山作青螺五髻鬟。","春日花开残雪里，僧房人在白云间。","善财参问何时遍，文畅嬉游几日还。","淮海清公更潇洒，早将闻见动禅关。"]},{"t":"寄广平太守郑彦章","f":"七言律诗","c":["湖山阻绝三千里，台阁勤劳十五年。","黄霸终然为宰相，赤松老矣号神仙。","洛阳城里还无屋，洺水村中好问田。","走也侯门旧宾客，白头不得与周旋。"]},{"t":"次顾清逸见寄韵","f":"七言律诗","c":["满目干戈独损神，古之忠义不谋身。","杜陵白发空忧国，王衍清谈已误人。","城郭秪今馀瓦砾，村墟何处避风尘。","妖氛不到西清上，千树桃花别有春。"]},{"t":"和娄所性韵就谢寄汉帖二本之诗","f":"七言律诗","c":["两帖真如白璧双，山灵呵护过沧江。","不知明月生春浦，每怪晴虹贯夜窗。","老去秪留诗卷在，愁来宁受酒杯降。","竹轩近喜多风致，活水栽荷满石缸。"]},{"t":"六月十三日闻边警甚急有感而作","f":"七言律诗","c":["边风六月作秋声，世事惊心百感生。","台阁故人犹嗜酒，闾阎小子亦谈兵。","红巾似草何时尽，白骨如山几日平。","甚欲移家渡江水，老来幽独最关情。"]},{"t":"寄黄观澜经历时率八卫汉军屯盱眙","f":"七言律诗","c":["秋满东南第一山，古来贤达几登攀。","两城楼阁西风里，八卫旌旂北斗间。","羽扇纶巾君未老，麻衣草座我空閒。","闭门拟撰平淮颂，河上来看奏凯还。"]},{"t":"送刘澹翁总管归江阴时年九十岁","f":"七言律诗","c":["曾侍家君接胜游，于今复见旧风流。","江湖诸老半黄壤，乡里小儿今白头。","车马在门为客好，干戈满地使人愁。","芙蓉城内宜高隐，丛桂山中莫久留。"]},{"t":"和孙行简夜宿万寿山经阁诗韵二首 其一","f":"七言律诗","c":["蜀冈缥缈之飞楼，风帘雾箔悬高秋。","云间五色孤凤下，木杪几个哀猿愁。","书生素有万言策，主人赠以千金裘。","沧江坐啸者谁子，碌碌虚名何足收。"]},{"t":"和孙行简夜宿万寿山经阁诗韵二首 其二","f":"七言律诗","c":["九曲池边看秋色，水光荡漾青于苔。","白云相邀上山去，明月更喜随人来。","一声两声松子落，千朵万朵芙蓉开。","老僧悟我静中意，不遣阶墀留俗埃。"]},{"t":"送庐山高斋赴南康监郡时兵火之馀在吴城山开司","f":"七言律诗","c":["公昔骑麟下星渚，前身恐是匡庐君。","孤城遗老穷无告，太守真符喜见分。","彭蠡帆樯明夕照，吴城旌旆拂秋云。","明年春殿论功赏，传奏先将姓字闻。"]},{"t":"送王彦芳之南台御史","f":"七言律诗","c":["南台二十四松厅，上应微垣执法星。","定有威名清广海，岂无章疏动朝廷。","铁冠精彩还簪笔，宝剑磨砻始发硎。","竹下明年候骢马，也应旌节照林坰。"]},{"t":"张仲举博士书来言其老健能夜书小字仍饮量不减喜而赋此诗录上","f":"七言律诗","c":["一秋两得平安报，读罢寒暄喜不胜。","花底振衣清似鹤，灯前书字小如蝇。","蜕仙道骨无人识，博士官衔自此升。","江上莼鲈好时节，岂无清梦到吴兴。"]},{"t":"癸巳九日","f":"七言律诗","c":["今年九日无一钱，杞菊满院秋娟娟。","闭门不出何所作，抱膝长吟真可怜。","城东买竹欲移屋，溪上种秫空求田。","馀生饱吃广陵饭，更拟作诗三十年。"]},{"t":"送徐州李判官供给役满归","f":"七言律诗","c":["千里旌旗接轴轳，王师日久费供需。","秪知天下金如土，岂谓人间米似珠。","此日论功犹受赏，何人报主肯忘躯。","讵无执法如公者，能上封章亦丈夫。"]},{"t":"挽王彦达","f":"七言律诗","c":["老来正赖君医我，客里那知我哭君。","人世百年修短定，江城一日死生分。","锦帆泾上谁家屋，龙井庄前处士坟。","魂魄东西招不得，杏花村落雨纷纷。"]},{"t":"送诗僧立平山住图山","f":"七言律诗","c":["东遐寺东遐只在，海门东二月西桥。","送远公明月不来，过竹下白云相引。","到山中早时彷佛，三生会何日风流。","一笑同少待春晖，野花发新诗还肯。"]},{"t":"寄衰翁东宫典宝监知事史仲文赴京之任赋诗二首为饯 其一","f":"七言律诗","c":["宫官比日盛才贤，寮寀光华得妙年。","东禁总分清切地，前星偏近紫微天。","朱研玉斗时开宝，香热金炉晓奏笺。","朝觐从容问先世，鄂公忠孝是家传。"]},{"t":"寄衰翁东宫典宝监知事史仲文赴京之任赋诗二首为饯 其二","f":"七言律诗","c":["征车载道马駉駉，更尽沙头双玉瓶。","十月淮南逢小雪，五云天上望前星。","龙文符宝连函出，鹤禁箫韶弭节听。","鄂国平南好勋业，嘉言何处惜朝廷。"]},{"t":"三月十八日同饶介之冯仁伯张道源王伯纯雅集城东李氏园亭赋此","f":"七言律诗","c":["三月雅集未知还，况复夕阳犹在山。","金刀刻字碧筠上，玉卮行酒青松间。","三年不见兵马息，一日且放吾侪闲。","桃花杏花正无数，明朝更约来东关。"]},{"t":"饶介之怀古有诗见和复用前韵以答 其一","f":"七言律诗","c":["江水东流去不还，几人不老似青山。","九洲目断苍烟水，万古魂销落照间。","石上鸟啼松树合，水边人羡柳花闲。","更容野客重携酒，为报园翁莫掩关。"]},{"t":"饶介之怀古有诗见和复用前韵以答 其二","f":"七言律诗","c":["自笑东园数往还，年年诗债积如山。","身游紫陌红尘外，心在青天白日间。","说剑谈玄俱是错，焚香酌酒不如闲。","先生自是知几者，莫放声名动紫关。"]},{"t":"送谢参军朝京二首 其一","f":"七言律诗","c":["万重玉帛会蓬莱，先报中吴进表来。","内使传宣催引见，舍人当殿拆封开。","干戈载戢龙颜喜，正朔重颁凤历回。","却袖天香上归骑，定分春色到苏台。"]},{"t":"送谢参军朝京二首 其二","f":"七言律诗","c":["霜落平原百草乾，出门何处望朝端。","山林白发相逢晚，风雪沧江欲别难。","使命岂辞行地远，圣恩还复与天宽。","群公定问君家世，能为苍生远祖安。"]},{"t":"次饶介之琼花诗韵","f":"七言律诗","c":["此花超出万花群，阑槛真如隔彩云。","琼馆曾蒙天一笑，玉箫空负月三分。","溶溶瑞露通宵下，细细香风隔院闻。","后土祠前春似梦，至今红袖客纷纷。"]},{"t":"赋得铁瓮城送杨克明之淮海书院山长","f":"七言律诗","c":["城郭犹存铁瓮基，英雄曾此重藩维。","天连故国山为垒，地设长江水作池。","西府尚凭东府壮，今人不让古人奇。","津亭我昔经行处，目送风帆有所思。"]},{"t":"送姚节卿摄崇明判官","f":"七言律诗","c":["画省归来驿路长，玉荆传道石田荒。","一春对酒悲时事，四月乘槎过海洋。","杀贼岂图金作印，转官行见绣为裳。","孤城民瘼思苏息，回首纶音赐宠光。"]},{"t":"和李克约东皋杂兴四首 其一","f":"七言律诗","c":["一春开遍雨中花，几向东园管物华。","老去始知身是客，愁来空拟醉为家。","江楼帘箔飞香雾，野寨旌旗绚采霞。","曳杖归来还自笑，夕阳原上数残鸦。"]},{"t":"和李克约东皋杂兴四首 其二","f":"七言律诗","c":["芍药花开江雨晴，几时重作看花行。","松间携妓从教俗，竹下留宾也自清。","一夜春愁无处著，三分月色为谁明。","贫家亦有琴堪典，好把平生意气倾。"]},{"t":"和李克约东皋杂兴四首 其三","f":"七言律诗","c":["闭户拙于公是非，似与江湖踪迹稀。","酒中从令客骂坐，爨下却念儿啼饥。","松江之鲈固可食，沙苑有鸟宜高飞。","干戈满地正如此，万水千山何处归。"]},{"t":"和李克约东皋杂兴四首 其四","f":"七言律诗","c":["李家园内好亭台，老去一春能几回。","街头酒贵我当买，陌上花开君不来。","长绳难系白日住，清镜莫掩朱颜催。","明朝有约速相就，慎勿打碎玻璃杯。"]},{"t":"送郑复初赴白沙蔡宅馆","f":"七言律诗","c":["翠竹白沙江上春，主人应喜得西宾。","邻翁送子去就学，野老引孙来拜人。","夜几看书红蜡短，晓盘供馔白鱼新。","边尘不到沧州上，我欲相从一问津。"]},{"t":"送周草窗归九江","f":"七言律诗","c":["太平宫馆化为尘，近得麻姑信未真。","但见江湖同逆旅，焉知天地有间人。","匡山白发归何晚，彭泽黄花赏更新。","老去苦无超世术，干戈满地独吾身。"]},{"t":"送李周南之浙西道","f":"七言律诗","c":["应辟江南肃政堂，君才十倍宪诸郎。","先公向已乘骢马，多士今还睹凤凰。","祖帐晓开山木霁，官船夜泊水花凉。","三吴民力诛求尽，当为明时振纪纲。"]},{"t":"送王仲沔御史除安庆府判","f":"七言律诗","c":["谪宦南来莫怨嗟，府中争喜判生花。","中朝正合持衡鉴，御史何曾负国家。","未忝阳城官有庳，全胜贾谊傅长沙。","终令国事还公等，会见明廷辨正邪。"]},{"t":"奉寄余廷心元帅是时出镇之舒州","f":"七言律诗","c":["保障江淮数十州，中流屹立见君侯。","苍生几堕巅厓苦，白发因分社稷忧。","虮虱竟年生介胄，貂蝉今日出兜鍪。","玉堂应有昌黎颂，刻在龙眠最上头。"]},{"t":"挽孙有道处士","f":"七言律诗","c":["广陵故旧渐消磨，白发伤心奈尔何。","马援车犹在乡里，黄公垆已隔山河。","百年华屋春风歇，八月荒原夜雨多。","乱后与君成永诀，几行衰泪洒烟萝。"]},{"t":"八月十五日闻真州官民溃窜道路蹂躏而死者不可胜言黄军因之剽掠则天长六合等处莽为邱墟矣","f":"七言律诗","c":["白沙消息苦难真，军事危如火上薪。","老去未能生报国，愁来只与死为邻。","豺狼夜啸逃亡屋，貔虎秋惊战伐尘。","怅望天长一条路，王师何处渡淮津。"]},{"t":"闰正月二十日闻泗州盱眙同日失守","f":"七言律诗","c":["野寨苍茫落照中，东征三载未成功。","黄金似土供儿戏，白骨如山泣鬼雄。","天狗星流军府动，水犀兵散弩台空。","于今人力消磨尽，谁念东南府库穷。"]},{"t":"挽郁谦德处士 其一","f":"七言律诗","c":["身阅升平近九旬，至今谦德动朝绅。","眼前耆旧无多传，乱后交游复几人。","龙顾青山开宅舍，鹤归华表离风尘。","荒原来见兵麾息，相从灵车泪满巾。"]},{"t":"挽郁谦德处士 其二","f":"七言律诗","c":["白首其如死别何，临风老泪若悬河。","耆英社在晨星少，禅智山空夜雨多。","薤露莫悲人换世，桑田曾见海生波。","殡宫空对棠梨发，更拟重携浊酒过。"]},{"t":"寄题西江罗隐君本心斋","f":"七言律诗","c":["江海翩然勇赋归，只从静里见天机。","一经断送休休了，万事消磨念念非。","隐几不知流水动，闭门常见白云飞。","若为同结斋中友，老向苍山采蕨薇。"]},{"t":"送淮南省掾王安中北上安中曾为今上说书秀才","f":"七言律诗","c":["说书妙选近丹墀，名姓曾为帝所知。","主父徒嗟相见晚，长卿毋谓不同时。","淮南曹事称仁恕，邺下民谣纪去思。","自古长才须大用，诸公久待凤凰池。"]},{"t":"甲午除夜有怀孟景章","f":"七言律诗","c":["夜窗儿女笑灯前，乱世安居又一年。","邻瓮且分蓝尾酒，客囊从换折腰钱。","冻消屋角筼筜雪，寒压炉头榾柮烟。","安得重陪孟东海，剧谈终夜不成眠。"]},{"t":"题观弈图吴善渊作","f":"七言律诗","c":["仙翁对弈古松根，当局机锋未易论。","只许两先饶日月，休将一著赌乾坤。","满盘星斗无人测，四角关河有路存。","樵子归来柯已烂，空山寥落又黄昏。"]},{"t":"王彦芳绣荣堂","f":"七言律诗","c":["色丝不染胭脂井，银汉缲成五色纹。","织女机中翻海水，谏官衣上绣春云。","清严地位人谁到，错综天章手自分。","他日锦归当白昼，江花江草亦欣欣。"]},{"t":"送澧州王伯颜治中公昔征蛮有功","f":"七言律诗","c":["南荒万里握戎机，共诧君侯奏凯归。","出界旧传铜作柱，过家新喜锦为衣。","梯航入贡鲸波远，溪洞消兵羽檄稀。","今日中原方用武，岂无卿相布天威。"]},{"t":"挽周古善尊师","f":"七言律诗","c":["看罢璚花去不还，今闻笙鹤在云间。","十洲何处留真迹，万古无人出此关。","林下故交同白发，江南旧业只青山。","丹经已付无为子，月夜犹疑响佩环。"]},{"t":"沙子中监县二子善才善庆俱登第因名其所居之山曰联桂所以纪瑞也诗以美之 其一","f":"七言律诗","c":["山翁高步月中来，移得灵根手自栽。","仙籍许令诸子折，君家先见两枝开。","双承御宴簪花出，并惹天香满袖回。","自笑淮南谩招隐，连蜷偃蹇老苍苔。"]},{"t":"沙子中监县二子善才善庆俱登第因名其所居之山曰联桂所以纪瑞也诗以美之 其二","f":"七言律诗","c":["桂丛竞发山之阿，大株小株秋婆娑。","灵鹫峰头月色薄，乌龙潭上天香多。","吴刚持斧不敢近，郗诜对策将如何。","岂惟二季在仙籍，诸孙还见援枝柯。"]},{"t":"和崔元初秋日舒怀感时叙旧情见乎辞 其一","f":"七言律诗","c":["淮南入幕皆名士，边土从军总贵游。","万里又劳丞相出，九重独使圣君忧。","禾生异亩虚占斗，木落空江欲变秋。","召伯埭前听报捷，高邮城外解通舟。"]},{"t":"和崔元初秋日舒怀感时叙旧情见乎辞 其二","f":"七言律诗","c":["荔薜墙空雨气深，湿苔满径竹森森。","城中不得三农信，塞上争禁十日阴。","野佃负薪多未得，邻翁乞米数相寻。","笙歌饮散者谁子，命驾归来醉堕簪。"]},{"t":"和崔元初秋日舒怀感时叙旧情见乎辞 其三","f":"七言律诗","c":["潇洒君家锦照堂，石泉秋水煮茶香。","沿池筱簜鞭尤润，当户蒲萄叶半黄。","东馆坏垣尘漠漠，西城残照晚苍苍。","春时数听尚书履，几送池边月色凉。"]},{"t":"赠惟善驸马野云亭","f":"七言律诗","c":["万里飞来广漠云，随时舒卷故缤纷。","风中不见孤飞迹，日下都成五色纹。","从尔所之占隐者，更堪持以献吾君。","明时用汝为霖雨，先向东南洗恶氛。"]},{"t":"六月二日书所见","f":"七言律诗","c":["干戈满地起风尘，民物凋零府库贫。","黄犊乌犍烹作食，雕梁画栋拆为薪。","江淮经理须贤俊，草泽诛求到隐沦。","漫道宽心应是酒，老夫三日不沾唇。"]},{"t":"小轩有菊一本盛开两花大如酒杯饶介之见而爱之连赋诗二首因次其韵 其一","f":"七言律诗","c":["菊下呼儿典缊袍，相看无酒目空蒿。","两花迭出金杯大，数叶轻攒翠羽高。","就手折来香澹澹，满头簪得乐陶陶。","曲生有意来相觅，留得芬芳荐蟹螯。"]},{"t":"小轩有菊一本盛开两花大如酒杯饶介之见而爱之连赋诗二首因次其韵 其二","f":"七言律诗","c":["满径香风吹客袍，却胜秋野醉攒蒿。","东篱隐者世不泯，南阳老人年最高。","大白杯中多趣味，中黄□内几钧陶。","莫令雨后荒三径，更趁霜前斫两螯。"]},{"t":"安庆大节堂至正十二年既陷武昌江州诸郡俱各失守时韩功懋总管守安庆指禦有方江淮赖为屏蔽廷心余帅书大节于堂以旌武功","f":"七言律诗","c":["战胜非难守胜难，逆图未伐胆先寒。","焉知天下无诸葛，始信军中有一韩。","当日雷霆归号令，至今烽火报平安。","雄文大扁同时出，大节名堂后代看。"]},{"t":"次饶介之述怀佳作 其一","f":"七言律诗","c":["读书不致卿相事，生计或与樵渔同。","杜门真是守株者，傍人过呼居童翁。","今晨把镜野服好，有月无酒山瓢空。","绿阴满地鸟声罢，向日独有葵花红。"]},{"t":"次饶介之述怀佳作 其二","f":"七言律诗","c":["千古万古道理大，海内海外车书同。","青山看世等过客，白发催人吾已翁。","干戈三载道路断，斤斧一朝林野空。","西轩拭泪付长叹，怅望夕阳天际红。"]},{"t":"题太湖李尹所收余廷心元帅书二封","f":"七言律诗","c":["两函妙墨古所见，一代高风人未知。","用兵不下羊叔子，食粥正如颜太师。","今日澄清在我辈，长江保障非公谁。","更烦令尹回州日，补入舒人遗爱碑。"]},{"t":"送拔寔彦卿被召之翰林直学士","f":"七言律诗","c":["天上仙人紫绮裘，偶题明月到扬州。","日边使者徵方急，泉下奸臣死亦羞。","宣室正思前席问，淮南谁赋小山幽。","玉堂信与人间隔，肯为琼花更少留。"]},{"t":"夜泊长桥","f":"七言律诗","c":["十丈虹蜺跨碧空，行人过此莫匆匆。","大鱼吹浪来船尾，明月流光出海东。","根本旧邦唇齿近，边廷诸将腹心同。","丰碑屹立书何事，特纪当年谢傅功。"]},{"t":"灯下有感","f":"七言律诗","c":["城郭空虚鸟乱鸣，彩旗拂柳夕阳明。","山林乐土非畴昔，兵火残民思太平。","海燕归来无旧主，野花满地有馀情。","一尊酹月悲歌后，搔首灯前百感生。"]},{"t":"金溪葛氏二孝烈女祠","f":"七言律诗","c":["葛女祠前荐荔蕉，藤花风雨急飘萧。","翠軿五夜灵氛下，银穴千年宝气销。","太史已闻书孝烈，遗民无复困征徭。","绛唇朱袖归黄土，惆怅何人说二乔。"]},{"t":"澹香亭","f":"五言绝句","c":["幽芳不自媚，白日净依依。","风露已如此，山中人未归。"]},{"t":"画枯木","f":"五言绝句","c":["老树半无叶，石根馀野花。","高秋上河汉，用汝作灵槎。"]},{"t":"墨兰","f":"五言绝句","c":["能让吴君子，伤谗楚大夫。","延陵无宿草，湘水有新蒲。"]},{"t":"晚兴","f":"五言绝句","c":["多景栖红树，秋风落白云。","捕鱼频得隽，惊鹭不成群。"]},{"t":"畎亩","f":"五言绝句","c":["畎亩心常白，江湖眼尚青。","悠悠今古路，一一短长亭。"]},{"t":"画竹","f":"五言绝句","c":["笔间珠树长，不借白云栽。","尽日看龙挂，空疑有雨来。"]},{"t":"赵承旨竹石","f":"五言绝句","c":["石间生石笋，笋长又成林。","林下纤纤草，王孙去国心。"]},{"t":"坐雨","f":"五言绝句","c":["行云都是梦，听雨甚于秋。","㶁㶁盈阶水，时时一尺流。"]},{"t":"居竹轩","f":"五言绝句","c":["定居人种竹，居定竹依人。","新笋甜于肉，长竿健似身。"]},{"t":"题倭僧所画菖蒲小景四首 其一","f":"五言绝句","c":["海上青毛鹤，山中绿发仙。","相期采九节，同尔寿千年。"]},{"t":"题倭僧所画菖蒲小景四首 其二","f":"五言绝句","c":["剑脊秋逾劲，鞭根老更繁。","何堪拜吾竹，尚可友溪荪。"]},{"t":"题倭僧所画菖蒲小景四首 其三","f":"五言绝句","c":["昔在嵩高日，仙人不可招。","独行南涧底，采得虎须苗。"]},{"t":"题倭僧所画菖蒲小景四首 其四","f":"五言绝句","c":["怪石玲珑白，方盆玛瑙红。","倭僧到中国，何处挹清风。"]},{"t":"和饶介之春夜七绝 其一","f":"五言绝句","c":["新月不落地，四更犹有光。","无人防白兔，窃夜捣玄霜。"]},{"t":"和饶介之春夜七绝 其二","f":"五言绝句","c":["涧松如老友，岁晚可同襟。","独立风尘表，悠悠千古心。"]},{"t":"和饶介之春夜七绝 其三","f":"五言绝句","c":["落日五湖上，独行逢故人。","有家如隔世，无物可通神。"]},{"t":"和饶介之春夜七绝 其四","f":"五言绝句","c":["我有太古竹，青天骑作龙。","明当渡江去，归听广陵钟。"]},{"t":"和饶介之春夜七绝 其五","f":"五言绝句","c":["沧浪波涛阔，昆崙世界多。","吾无缩地法，谁有步天歌。"]},{"t":"和饶介之春夜七绝 其六","f":"五言绝句","c":["酒量尚一斗，鬓丝馀几茎。","辛夷开欲罢，何日问归程。"]},{"t":"和饶介之春夜七绝 其七","f":"五言绝句","c":["昨夜马头雹，满天羊角风。","吹灯不敢寐，愁坐欲书空。"]},{"t":"题三友轩汤直学求赋三首 其一","f":"五言绝句","c":["古松存古操，岂意受秦封。","岁晚风尘表，空山作卧龙。"]},{"t":"题三友轩汤直学求赋三首 其二","f":"五言绝句","c":["吾亦怜吾竹，孤清人未知。","向来多俗病，全得此君医。"]},{"t":"题三友轩汤直学求赋三首 其三","f":"五言绝句","c":["古梅如古士，岁晚托同襟。","不作玉堂梦，山林深更深。"]},{"t":"题宋子章竹","f":"七言绝句","c":["黄陵只在断云西，苦竹丛深望欲迷。","帝子不归春又晚，满林烟雨鹧鸪啼。"]},{"t":"洞宾出山像","f":"七言绝句","c":["散发空山只短衣，古来豪杰在知机。","无人识是纯阳子，万壑千岩独自归。"]},{"t":"邓孝子行卷二首 其一","f":"七言绝句","c":["歌罢河东孝子诗，满堂宾客动嗟咨。","何由得著斓斑服，一日娱亲十二时。"]},{"t":"邓孝子行卷二首 其二","f":"七言绝句","c":["哭尽秋天月不明，哀容憔悴欲无生。","泪痕渍入泉台石，万古千秋父子情。"]},{"t":"徽庙御画栀子白头翁","f":"七言绝句","c":["栀子红时人正愁，故宫衰草不胜秋。","西风吹落青城月，啼得山禽也白头。"]},{"t":"客中久雨","f":"七言绝句","c":["水满行厨欲产蛙，苔封老屋乱啼鸦。","南风十日黄梅雨，开尽冬青两树花。"]},{"t":"送刘将军致仕归襄阳 其一","f":"七言绝句","c":["当年铁马渡襄江，敌国闻风夜纳降。","今日却归江上去，岘山青满读书窗。"]},{"t":"送刘将军致仕归襄阳 其二","f":"七言绝句","c":["五月楼船始到家，山中无处不桑麻。","今人却笑东门老，白发春田独种瓜。"]},{"t":"秋塘戏鹅图","f":"七言绝句","c":["满塘秋水看苍鹅，草软沙平奈尔何。","记得一群黄似酒，杏花梁上落红多。"]},{"t":"春夜","f":"七言绝句","c":["酒兵无力破愁城，春尽空山杜宇声。","敲缺唾壶眠不得，半帘花影月三更。"]},{"t":"赠刘生","f":"七言绝句","c":["玉堂官纸白于银，曾为山人写绿筠。","绝似潇湘烟雨外，万竿浓翠拂秋旻。"]},{"t":"送僧南归 其一","f":"七言绝句","c":["门外青山翠作堆，好怀能为故人开。","浮杯不渡清淮水，却过西轩看竹来。"]},{"t":"送僧南归 其二","f":"七言绝句","c":["芒履犹香楚地花，一瓶随处是生涯。","不须乞食游女去，舍利城多长者家。"]},{"t":"青山白云图","f":"七言绝句","c":["不见茅斋旧隐君，绕溪烟树暮纷纷。","断桥水满无人渡，谁向青山管白云。"]},{"t":"墨梅","f":"七言绝句","c":["东阁冲寒雪一枝，巡檐偏解索题诗。","何郎老去风情减，羞见疏花照鬓丝。"]},{"t":"夜宿野城","f":"七言绝句","c":["露气涓涓欲二更，小舟犹向月中行。","前村知有人家近，隔浦微闻犬吠声。"]},{"t":"草虫卷子 其一","f":"七言绝句","c":["蜗名蝶梦总成空，络纬徒知纺绩功。","何似螳螂化蝉去，最高枝上吸清风。"]},{"t":"草虫卷子 其二","f":"七言绝句","c":["鸣蜩织女共惊秋，嗟尔微虫死即休。","瞋目斗蛙犹未已，请看粘壁缀蜗牛。"]},{"t":"正月晦日","f":"七言绝句","c":["问余何事日匆匆，把卷题诗转不工。","捡历又看正月过，一分春在酒杯中。"]},{"t":"画马","f":"七言绝句","c":["圉人争喜得骅骝，拨入天闲早见收。","今日有谁怜骏骨，西风沙苑蕨藜秋。"]},{"t":"送人之武林","f":"七言绝句","c":["白鼻骄騧紫绮裘，涌金门外醉瀛洲。","君家若有平安字，寄在春风第几楼。"]},{"t":"题四明太守丁宴学官卷子","f":"七言绝句","c":["庄严七宝供西僧，甲第纷纷竞割烹。","独有四明贤太守，杏坛春酒宴诸生。"]},{"t":"武林客舍","f":"七言绝句","c":["窗外青山啼子规，吟魂正被酒禁持。","小楼一夜雨声恶，落尽碧桃人未知。"]},{"t":"绿杨桥","f":"七言绝句","c":["长溪春涨碧溶溶，烟雨空濛湿采虹。","何事吹箫度清夜，断堤杨柳月明中。"]},{"t":"清泉寺","f":"七言绝句","c":["何人泉上记清游，茶具横陈晚未收。","木叶尽随风扫去，万山清立寺门秋。"]},{"t":"题高房山墨竹","f":"七言绝句","c":["黄花山主澹游翁，写竹依稀篆籀工。","独有高侯知此趣，一枝含碧动秋风。"]},{"t":"题张天民移居图","f":"七言绝句","c":["旧隐荆溪第几村，手栽松桧至今存。","大茅峰下千年鹤，迟汝重来问子孙。"]},{"t":"同郑德明访宝昙上人不遇赋此二绝 其一","f":"七言绝句","c":["白云林下诵经寮，隔岸香风远更飘。","欲就禅床吃茶处，倩人扶过木长桥。"]},{"t":"同郑德明访宝昙上人不遇赋此二绝 其二","f":"七言绝句","c":["打门来访宝昙僧，松下云深唤未应。","谁识三生旧行路，断崖苍藓络枯藤。"]},{"t":"题邓毅夫所藏青山白云图","f":"七言绝句","c":["山后山前暝不分，草堂无径觅徵君。","惟馀玉气无藏处，散入空青作白云。"]},{"t":"高昌王所画蒲萄熊九皋藏","f":"七言绝句","c":["玉关西去火州城，五月蒲萄无数生。","今日江南池馆里，万株联络水晶棚。"]},{"t":"云山小景","f":"七言绝句","c":["我家草堂南涧滨，门前不识车马尘。","白云相随过山去，天地别有人间春。"]},{"t":"青山白云图","f":"七言绝句","c":["溪上长松已合围，草堂无事客来稀。","湿云生满东山路，日暮野樵何处归。"]},{"t":"唐明皇吹箫图二首 其一","f":"七言绝句","c":["寝殿春深昼漏迟，榻前侍女立多时。","玉箫自按霓裳曲，赐与梨园子弟吹。"]},{"t":"唐明皇吹箫图二首 其二","f":"七言绝句","c":["花萼楼前柳色新，东风吹散马嵬尘。","锦囊玉管俱零落，谁是终南梦里人。"]},{"t":"题蒲塘双燕图为刘小斋作","f":"七言绝句","c":["昭阳池馆晚风微，花落巢空去未归。","却是蒲塘春水阔，年年还傍小斋飞。"]},{"t":"九月十二日出北郊","f":"七言绝句","c":["官河两岸土城低，旗帜青红望欲迷。","万木千林谁伐尽，数家茅屋野乌啼。"]},{"t":"竹枝歌 其一","f":"七言绝句","c":["道士庄前秋事多，东家西家收晚禾。","船头把酒对明月，听打夜场人唱歌。"]},{"t":"竹枝歌 其二","f":"七言绝句","c":["乔麦花开如白烟，并催农事了霜前。","晚禾未割豆先熟，双髻女儿齐下田。"]},{"t":"题獐猿便面","f":"七言绝句","c":["树上孤猿树下獐，山林物性各相忘。","不知万里中原阔，鹰犬交驰苜蓿场。"]},{"t":"访王伯纯晚归","f":"七言绝句","c":["长洲苑内旧池台，白发山人恰再来。","无限客愁浑忘却，小楼听雨杏花开。"]},{"t":"和饶介之秋怀诗韵 其一","f":"七言绝句","c":["邻瓮新篘曲米香，梦魂夜夜绕槽床。","故人不饮今何在，秋尽空山苜蓿长。"]},{"t":"和饶介之秋怀诗韵 其二","f":"七言绝句","c":["江风吹尽暮天霞，我本淮人来寄家。","吴门留滞不归去，开尽西轩白鹤花。"]},{"t":"和饶介之秋怀诗韵 其三","f":"七言绝句","c":["夜半金乌海上翔，行来夹日酷于霜。","庭前几个芭蕉叶，未到秋分一半黄。"]},{"t":"和饶介之秋怀诗韵 其四","f":"七言绝句","c":["铁锁沧江第几关，扬州花竹梦中看。","也知无赖三分月，照见沙场白骨寒。"]},{"t":"和饶介之秋怀诗韵 其五","f":"七言绝句","c":["月落未落明星高，宿云卷尽无秋毫。","中庭隐几复假寐，候虫四壁声劳劳。"]},{"t":"和饶介之秋怀诗韵 其六","f":"七言绝句","c":["湖面茨莼叶半舒，湖中新出四腮鱼。","黄金换酒须当醉，莫信黄金可贮储。"]},{"t":"和饶介之秋怀诗韵 其七","f":"七言绝句","c":["凤凰桥西淮子河，年年租吏夜催科。","秪今田父无消息，豹虎满天将奈何。"]},{"t":"和饶介之秋怀诗韵 其八","f":"七言绝句","c":["氛祲冥冥晚未消，浙江三日不通潮。","令人却忆冯公子，知在西湖第几桥。"]},{"t":"和饶介之秋怀诗韵 其九","f":"七言绝句","c":["彭泽归来落落然，风流不写义熙年。","东篱菊种无寻处，老树荒台锁暮烟。"]},{"t":"和饶介之秋怀诗韵 其十","f":"七言绝句","c":["横江孤鹤翅如轮，一别山林五百春。","肯借老夫骑过海，方壶圆峤少风尘。"]},{"t":"再次韵 其一","f":"七言绝句","c":["花烛银台沈水香，为郎先暖合欢床。","小姑纳聘山堂上，缠酒红绡十丈长。"]},{"t":"再次韵 其二","f":"七言绝句","c":["横江江水荡晴霞，秋尽夫君不到家。","闺中小鬟也浪语，陌上听歌杨白花。"]},{"t":"再次韵 其三","f":"七言绝句","c":["写就安书无便翔，寒衣著破过三霜。","但记送郎初上马，窄袖短衫穿柳黄。"]},{"t":"再次韵 其四","f":"七言绝句","c":["西到长干过几关，附得书来侬自看。","八疋四川十样锦，裁作郎衣遮早寒。"]},{"t":"再次韵 其五","f":"七言绝句","c":["竹枝歌比柳枝高，红纸乌丝紫兔毫。","夫婿从军不识字，殷勤写去也徒劳。"]},{"t":"再次韵 其六","f":"七言绝句","c":["阿翁生儿如阿舒，少年不殊同队鱼。","但见门前有人客，肯信箧中无积储。"]},{"t":"再次韵 其七","f":"七言绝句","c":["老翁买舟西市河，去应不求闻达科。","阿婆牵衣翁且住，下第归来将奈何。"]},{"t":"再次韵 其八","f":"七言绝句","c":["洞庭山岚犹未消，炮车云起怕风潮。","劝郎把舵莫放手，水恶须防第四桥。"]},{"t":"再次韵 其九","f":"七言绝句","c":["江头野花红欲然，春去秋来不记年。","寻得秦皇系缆石，青沙一色草如烟。"]},{"t":"再次韵 其十","f":"七言绝句","c":["鸳鸯湖西湖水凉，踏藕采莲来觅郎。","郎意莫如菱刺短，妾情只似藕丝长。"]},{"t":"再次韵 其十一","f":"七言绝句","c":["江南秋熟转饥寒，头上犹簪列士冠。","鸡犬全家上天去，学仙悔不事刘安。"]},{"t":"题南竹","f":"七言绝句","c":["洞庭南去竹如云，老叶新梢乱不分。","帝子不归风雨恶，深林何处觅湘君。"]},{"t":"题宫人汲井","f":"七言绝句","c":["辘轳轻转汲清泠，玉碗盛来进内庭。","别院有人愁似海，眼花落井怨银瓶。"]},{"t":"杂赋五首 其一","f":"七言绝句","c":["民间升斗籴仓陈，五十青钱一束薪。","黑潦满街风雨恶，日中犹有未炊人。"]},{"t":"杂赋五首 其二","f":"七言绝句","c":["农父驱牛晓入城，可怜牛卖尽遭烹。","明年湖上休兵后，一寸荒田不得耕。"]},{"t":"杂赋五首 其三","f":"七言绝句","c":["破钱羞涩客囊倾，菜把青青价稍平。","却喜来朝知肉味，敢云何处有鱼羹。"]},{"t":"杂赋五首 其四","f":"七言绝句","c":["高阳社里醉复醒，于今老友俱凋零。","街头酒薄不堪饮，四百青钱沽一瓶。"]},{"t":"杂赋五首 其五","f":"七言绝句","c":["十月一日河上行，军中少年知姓名。","谁家一儿驾艇子，肯载老夫同入城。"]},{"t":"哭马士明都事 其一","f":"七言绝句","c":["冥冥妖祲黑如云，湖上旌旗乱不分。","父子四人同战死，边庭谁说马将军。"]},{"t":"哭马士明都事 其二","f":"七言绝句","c":["干戈未定失英雄，野寨无人战舰空。","三十六陂波浪恶，故人何处哭秋风。"]},{"t":"题徐仲原所藏王冕画红梅","f":"七言绝句","c":["罗浮仙子绛绡裳，也欲随时学艳妆。","今日北人浑见惯，杏花同色不同香。"]},{"t":"燕中怀古章贡侍御","f":"五言古诗","c":["娉婷二八女，绝色妙难画。","新妆薄铅华，照影修竹下。","盛年事夫婿，锦玉耀精舍。","虽非伯鸾妻，惓惓惜春夜。","琴馀月当轩，默默倚风榭。","寄语东家儿，红颜莫轻嫁。"]},{"t":"送李子威代祀嵩衡淮海","f":"五言古诗","c":["群生望甘泽，五岳云气通。","天香落岩谷，瑞霭春冥濛。","海潮天际来，金碧森万峰。","划落紫翠堆，亭亭玉芙蓉。","古庙丝竹存，迎神奏黄钟。","空山递馀响，落花舞青童。"]},{"t":"送人归桐江","f":"七言律诗","c":["读书不谒万乘君，挟策肯傍诸侯门。","啸歌苏台晚山碧，濯足洞庭秋水浑。","千金未易买骏骨，一饭岂足哀王孙。","风尘拂衣且归去，高卧桐江烟水村。"]},{"t":"送王止善归茅山","f":"七言律诗","c":["句曲仙人止善君，乱离何处避尘氛。","独乘一苇淩沧海，谁共三茅管白云。","丹井洗瓢分石髓，宝函封检秘天文。","他年定有方壶约，几夜苏台候鹤群。"]},{"t":"游平江瑞光寺","f":"七言律诗","c":["水殿云廊取次开，不论庐阜与天台。","窗间燕雀驯相近，池上龟鱼唤亦来。","春雨久荒红药圃，香烟遍烧碧莲台。","上方似可容吾隐，也伴高僧坐石苔。"]},{"t":"送学无遇长老归江南","f":"七言律诗","c":["新赐袈裟染茜红，拈花消息悟灵峰。","大开海会容三教，远致嵩呼祝九重。","贝叶有书驮白马，葛藤无语问黄龙。","湖船满载燕山月，归照招提万树松。"]},{"t":"送钱万户归泉南","f":"七言律诗","c":["八月归来下泽车，将军此意复何如。","十年不佩封侯印，万卷惟收教子书。","风月祇今尊有酒，江湖何处食无鱼。","建溪为谢罗从事，久不题诗寄竹居。"]},{"t":"吊顾野王故居","f":"七言律诗","c":["宝云寺里旧祠堂，自汲清泉酬野王。","白马有神嘶古道，青衣无梦到禅床。","尘销坏壁书千卷，土蚀残碑字几行。","欲借《玉篇》遗稿看，山僧无语立斜阳。"]},{"t":"陈朝桧","f":"七言律诗","c":["千年老桧上青霄，三阁花飞不动摇。","香骨自来盘左纽，苦心未忍弃前朝。","蛟龙并立江云黑，鸾凤双啼海雾消。","想得龟蒙题咏处，殿头风雨正萧条。"]},{"t":"题倪幻霞云松图","f":"七言绝句","c":["九峰只在泖云西，松下来寻隐者栖。","隐者不归空见画，满山风雨夜猿啼。"]},{"t":"至正二十一年春三月二日同孙大雅张孟肤縻仲明登虎丘访居中禅师不遇留题平远堂","f":"曲","c":["三月二日春增华，泛舟也到王珣家。","山中碧泉似?醁，岩下绿草如袈裟。","荒坟无人见白虎，新城有树啼青鸦。","居中老禅不得会，空索剑池同煮茶。"]},{"t":"赠绫锦墩隐者钱庆馀","f":"七言律诗","c":["手拄乌藤五尺长，山行时著古衣裳。","缺文自补云间志，卖药多收海上方。","茆屋秋风催酿秫，锦墩春雨看移桑。","野人笑指长安路，马足车尘有底忙。"]}]};